INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6857', 'spa', 'Sefat (ciudad cananea, después llamada Horma)', 'Este topónimo identifica una ciudad cananea que Judá y Simeón conquistaron y luego renombraron Horma («destrucción»). Jueces 1:17 registra la conquista y el cambio de nombre. El nombre original Sefat y el nuevo nombre Horma reflejan el destino de la ciudad: fue consagrada a la destrucción total. Se han propuesto diversas ubicaciones para su identificación, incluidos sitios en el Néguev al sur de Judá. La práctica de renombrar reflejaba la comprensión teológica de Israel de que esta ciudad había sido puesta bajo el anatema de la guerra santa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6858', 'spa', 'capitel (remate decorativo de una columna), parte superior chapada en metal', 'Este sustantivo aparece únicamente en 2 Crónicas 3:15, donde describe elementos arquitectónicos del templo de Salomón. Se refiere al capitel, es decir, la parte superior decorada de una columna o pilar. El término sugiere que estos capiteles estaban revestidos o chapados con metal precioso. Los dos pilares que se alzaban frente al templo —Jaquín y Boaz— eran imponentes obras arquitectónicas, y sus elaborados capiteles coronaban estas monumentales columnas. Este detalle refleja tanto la grandiosidad de la construcción del templo como la importancia que se daba a registrar sus especificaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6859', 'spa', 'Sefata (valle cercano a Maresa en Judá)', 'Este topónimo designa un valle cercano a Maresa donde el rey Asá de Judá se enfrentó al ejército invasor etíope. 2 Crónicas 14:10 sitúa la batalla «en el valle de Sefata, junto a Maresa». Aunque su ubicación exacta es debatida —la Septuaginta lo tradujo como «al norte», lo que ha llevado a algunos a enmendar el texto—, claramente identifica un accidente geográfico asociado con Maresa en la región de la Sefela de Judá. Fue aquí donde el ejército muy inferior de Asá obtuvo una victoria decisiva al confiar en el Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6860', 'spa', 'Siclag, una ciudad filistea en el Néguev otorgada por Aquis de Gat a David durante su exilio. Siclag (צִקְלַג) era una ciudad fronteriza en el sur del', 'Siclag, una ciudad filistea en el Néguev otorgada por Aquis de Gat a David durante su exilio. Siclag (צִקְלַג) era una ciudad fronteriza en el sur del Néguev, originalmente asignada tanto a Judá (Jos 15:31) como a Simeón (Jos 19:5; 1 Cr 4:30), pero en poder de los filisteos en tiempos de Saúl. Cuando David huyó de Saúl, el rey Aquis de Gat le concedió Siclag como feudo personal, y permaneció como propiedad real de Judá ''hasta el día de hoy'' (1 Sam 27:6). La incursión amalecita y el incendio de la ciudad mientras David estaba ausente provocaron una de las grandes crisis de sus años como fugitivo (1 Sam 30:1–26), y la noticia de la muerte de Saúl le llegó a David allí (2 Sam 1:1; 4:10). Guerreros de diversas tribus se unieron a David en Siclag (1 Cr 12:1, 20). Pobladores postexílicos reocuparon el sitio (Neh 11:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6861', 'spa', 'saco, alforja, bolsa (para transportar provisiones)', 'Este sustantivo aparece únicamente en 2 Reyes 4:42, aunque su significado exacto sigue siendo algo incierto. El contexto describe a un hombre que lleva primicias a Eliseo en algún tipo de recipiente. Las versiones antiguas sugieren que podría tratarse de una prenda de vestir o de una bolsa o alforja. La lectura más probable, respaldada por cognados árabes, lo entiende como un saco o alforja para transportar provisiones. El hombre trajo veinte panes de cebada y grano fresco en este saco al profeta, provisión que milagrosamente alimentaría a cien hombres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6862a', 'spa', 'Estrecho, angosto, apretado (adjetivo); adversario o enemigo (uso sustantivado).', 'El adjetivo צַר describe constricción física: un lugar estrecho, un espacio demasiado angosto, un pasaje demasiado apretado. La burra de Balaam queda atrapada en un sendero estrecho (Núm 22:26), la vivienda de los profetas es demasiado reducida para su grupo (2 Re 6:1), y las escamas del cocodrilo están selladas apretadamente como un sello (Job 41:15). La raíz de esta palabra se superpone con el campo semántico hebreo más amplio de angustia y presión, y en Isaías 59:19 pasa de describir un espacio a describir una persona: el adversario que oprime, traducido como Bedränger («opresor») en alemán y shatru en hindi. Esta doble dimensión espacial y personal revela cómo el hebreo proyecta la constricción física sobre la hostilidad relacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6862b', 'spa', 'Estrechez, angustia o aflicción; también un adversario o enemigo personal que causa sufrimiento', 'Estrechez, angustia o aflicción; también un adversario o enemigo personal que causa sufrimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6862c', 'spa', 'Adversario, enemigo u opresor; también estrechez o angustia como estado abstracto de aflicción.', 'Adversario, enemigo u opresor; también estrechez o angustia como estado abstracto de aflicción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6862d', 'spa', 'pedernal, piedra dura o guijarro', 'Este sustantivo designa el pedernal o piedra muy dura, y aparece únicamente en Isaías 5:28. El profeta lo emplea en un símil que describe la preparación del ejército asirio: los cascos de sus caballos son duros «como pedernal». Esta comparación resalta la fuerza, la durabilidad y quizás la capacidad de producir chispas. La dureza del pedernal lo hacía valioso tanto para fabricar herramientas como para la imaginería metafórica. Algunos proponen leerlo como «roca» en sentido general, pero «pedernal» capta mejor la connotación específica de una dureza excepcional y la capacidad de resistir sin desgastarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6863', 'spa', 'Ser (ciudad fortificada en el territorio de Neftalí)', 'Este topónimo identifica una de las ciudades fortificadas en la heredad tribal de Neftalí. Josué 19:35 la enumera entre los asentamientos fortificados asignados a esta tribu del norte. El nombre parece ser una forma abreviada que posiblemente signifique «roca» o «pedernal», aunque esto sigue siendo incierto. La traducción griega lo vertió como «Tiro», pero probablemente se trató de una confusión y no de una referencia a la famosa ciudad costera. La ubicación exacta de Ser se desconoce, aunque era lo suficientemente importante como para figurar entre los centros urbanos fortificados de Neftalí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6865', 'spa', 'Tiro -- la gran ciudad costera fenicia, célebre por su comercio, su poderío marítimo y la púrpura tiria', 'Tiro -- la gran ciudad costera fenicia, célebre por su comercio, su poderío marítimo y la púrpura tiria');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6866', 'spa', 'ser abrasado, chamuscado, quemado (por fuego de juicio divino)', 'Este verbo en su forma Nifal significa ser abrasado o chamuscado por el fuego. Ezequiel 21:3 (20:47 en la numeración inglesa) lo emplea en una profecía contra la tierra, declarando que todos los rostros serán abrasados por las llamas. El contexto es el juicio divino representado como un fuego inextinguible que consume la tierra de sur a norte. La voz pasiva subraya que las personas son receptoras de este castigo ardiente, no sus agentes. La imagen es vívida y aterradora: un juicio total que no perdona a nadie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6867a', 'spa', 'abrasador, ardiente (del fuego o de las palabras)', 'Este adjetivo describe algo abrasador o ardiente. Proverbios 16:27 lo utiliza metafóricamente, comparando el habla de una persona indigna con un «fuego abrasador»: sus palabras queman y destruyen. El símil vincula la destructividad verbal con el dolor de una quemadura. Así como el fuego abrasador carboniza y daña todo lo que toca, el habla maliciosa hiere y causa estragos. La forma femenina concuerda con «fuego», resaltando la cualidad ardiente y corrosiva tanto de las llamas literales como del discurso figurado que quema como fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6869b', 'spa', 'Angustia, aflicción, tribulación — adversidad personal o nacional (singular); casos concretos de problemas o adversidades repetidas (plural).', 'Angustia, aflicción, tribulación — adversidad personal o nacional (singular); casos concretos de problemas o adversidades repetidas (plural).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6869c', 'spa', 'esposa rival, coesposa (en un hogar polígamo)', 'Este sustantivo femenino designa a una esposa rival en un hogar polígamo. En 1 Samuel 1:6 se utiliza para describir la relación de Penina con Ana: era su rival, su coesposa. El término conlleva inherentemente connotaciones de tensión y competencia, ya que varias esposas rivalizaban por la atención y el favor de su marido, especialmente en lo tocante a la descendencia. La raíz sugiere provocación o aflicción, lo cual encaja con una relación marcada por los celos y la rivalidad. La provocación constante de Penina hacia Ana, quien no podía concebir, ejemplifica la dolorosa dinámica que este sustantivo encierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6870', 'spa', 'Sarvia — hermana (o media hermana) de David, madre de los guerreros Joab, Abisai y Asael', 'Sarvia — hermana (o media hermana) de David, madre de los guerreros Joab, Abisai y Asael');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6871', 'spa', 'Zerúa (madre del rey Jeroboam I)', 'Este nombre propio identifica a la madre de Jeroboam I, el primer rey del reino del norte tras la división de la monarquía unida de Salomón. 1 Reyes 11:26 ofrece esta referencia materna, señalando que era viuda. En el antiguo Israel, identificar a alguien a través de su madre era menos frecuente que a través de su padre, lo cual hace esta mención especialmente notable. El nombre podría relacionarse con raíces que sugieren aflicción o lepra, aunque esto permanece incierto. Su viudez y el ascenso de su hijo al trono desde orígenes no reales son detalles significativos en la narrativa de Jeroboam.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6872a', 'spa', 'Atado, paquete (objetos ligados); bolsa, bolsillo, monedero (recipiente para objetos de valor)', 'El sustantivo צְרוֹר designa algo atado o envuelto, y sus dos acepciones giran en torno a qué se ata y con qué propósito. Como atado, se refiere a objetos reunidos y amarrados juntos: los hermanos descubren atados de dinero en sus costales (Gn 42:35), y al amado se le compara con un manojito de mirra (Cnt 1:13). Como bolsa o monedero, nombra un recipiente para guardar cosas de valor: una bolsa de dinero para el viaje (Pr 7:20), una bolsa agujereada por donde se escapan los salarios (Hag 1:6), o el saco sellado donde Dios guarda la transgresión (Job 14:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6872c', 'spa', 'Zeror (ancestro benjaminita de Saúl, abuelo de Quis)', 'Este nombre propio aparece en la genealogía de Saúl como su bisabuelo. 1 Samuel 9:1 traza el linaje de Saúl a través de Quis (su padre), Abiel, Zeror y Becorat hasta Afía, todos benjaminitas. Estos detalles genealógicos establecían las credenciales tribales de Saúl y la posición de su familia dentro de la tribu de Benjamín. El nombre podría derivarse de raíces que sugieren atar o envolver, aunque su significado preciso es incierto. Estos nombres ancestrales arraigaban al primer rey de Israel dentro de la estructura tribal de Benjamín, proporcionándole legitimidad y contexto para su elección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6874', 'spa', 'Zeri (músico levita, hijo de Jedutún)', 'Este nombre propio identifica a uno de los músicos levitas designados por David para el culto en el templo. 1 Crónicas 25:3 enumera a Zeri entre los hijos de Jedutún que profetizaban con liras, arpas y címbalos. El mismo individuo aparece como Izri en el versículo 11, lo que refleja variantes ortográficas de un mismo nombre. Estos músicos no eran simples intérpretes, sino que participaban en una adoración profética, empleando la música como vehículo de alabanza inspirada. A Zeri/Izri le correspondió el tercer turno en la organización de los músicos del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6875', 'spa', 'Bálsamo, resina aromática curativa de Galaad; comerciada como mercancía y usada metafóricamente como remedio espiritual.', 'Una resina aromática o bálsamo, probablemente del lentisco o del árbol de bálsamo, estrechamente vinculada a la región de Galaad. Se comercializaba como mercancía valiosa: la caravana de ismaelitas que llevó a José a Egipto transportaba tsori entre sus productos (Gn 37:25), y Jacob lo envió como obsequio al gobernante egipcio (Gn 43:11). En Jeremías, el bálsamo de Galaad se convierte en una de las metáforas más memorables de la Escritura: ''¿No hay bálsamo en Galaad?'' (Jer 8:22), pregunta retórica que lamenta que la sanación espiritual está disponible pero es rechazada. Ezequiel 27:17 lo incluye entre las exportaciones de Judá a Tiro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6876', 'spa', 'Tirio; perteneciente o relativo a Tiro, ciudad costera fenicia', 'Adjetivo gentilicio que identifica a alguien o algo como perteneciente a Tiro, la gran ciudad portuaria fenicia. Aparece en relación con Hiram, el artesano experto descrito como ''un hombre tirio'' que trabajó en el templo de Salomón (1 R 7:14; 2 Cr 2:14). El plural ''los tirios'' designa a los habitantes de Tiro que suministraron madera de cedro a David y Salomón (1 Cr 22:4; Esd 3:7) y que comerciaban pescado en Jerusalén en sábado, para disgusto de Nehemías (Neh 13:16). Las traducciones españolas ''tirios'' y ''de Tiro'' reflejan esta doble función adjetival y sustantiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6877', 'spa', 'fortaleza, cámara subterránea, lugar fortificado de refugio', 'Término de significado incierto que probablemente designa una fortaleza, un lugar fortificado o posiblemente una cámara subterránea o cueva utilizada como refugio. Jueces 9:46 y 49 mencionan la «fortaleza del templo de El-berit» donde los siquemitas se refugiaron (sin éxito) de Abimelec. Primer Samuel 13:6 lo incluye entre diversos escondites donde los israelitas huyeron de los filisteos: cuevas, espesuras, rocas, tumbas y cisternas. Las versiones antiguas lo tradujeron como «fortaleza» o «torre», pero el referente arquitectónico exacto sigue siendo incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6878', 'spa', 'necesidad, requerimiento, lo que se precisa', 'Este sustantivo arameo significa necesidad o requerimiento. Aparece únicamente en 2 Crónicas 2:16 (2:15 en algunas versiones), donde Hiram de Tiro responde a la solicitud de Salomón prometiendo suministrar madera «conforme a toda tu necesidad». El término subraya suficiencia y plenitud: Hiram proporcionaría la cantidad que Salomón requiriera, no una cifra predeterminada, sino lo suficiente para cubrir la totalidad del proyecto de construcción. El uso de vocabulario arameo refleja la correspondencia diplomática internacional entre ambos reinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6879', 'spa', 'Estar afligido con una enfermedad de la piel (lepra); como sustantivo, un leproso; como adjetivo, leproso. Verbo denominativo de צָרַעַת (enfermedad c', 'Estar afligido con una enfermedad de la piel (lepra); como sustantivo, un leproso; como adjetivo, leproso. Verbo denominativo de צָרַעַת (enfermedad cutánea, tradicionalmente ''lepra''), usado exclusivamente en formas pasivas para describir a alguien afectado por esta condición. El participio pasivo Qal (צָרוּעַ) y el participio Pual (מְצֹרָע) funcionan indistintamente como adjetivos y sustantivos. La palabra conlleva un peso ritual enorme: el מְצֹרָע debe habitar fuera del campamento, gritar ''¡impuro!'' (Levítico 13:45-46) y someterse a ritos de purificación elaborados (Levítico 14). Los relatos de Naamán (2 Reyes 5), Uzías (2 Crónicas 26:20-23) y los cuatro leprosos a la puerta de Samaria (2 Reyes 7:3) hacen de esta condición uno de los símbolos bíblicos más vívidos tanto de aflicción como de soberanía divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6880', 'spa', 'avispón; insecto que pica enviado por Dios como arma contra los enemigos de Israel', 'El avispón aparece como arma divina—Dios promete enviar avispones delante de Israel para expulsar a los cananeos. Éxodo 23:28 y Deuteronomio 7:20 presentan esto como parte de la estrategia de conquista: el Señor enviará el avispón delante del pueblo para expulsar a los habitantes. Josué 24:12 recuerda el cumplimiento: ''Envié el avispón delante de ustedes.'' Ya sean insectos literales o una metáfora de terror y pánico, el avispón representa la intervención activa de Dios desmantelando la resistencia enemiga. El artículo definido (''el avispón'') sugiere un fenómeno conocido o símbolo del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6881', 'spa', 'Zora; ciudad danita en la Sefelá de Judá, cuna de Sansón y punto de partida de la migración danita.', 'Zora (también Tsorah o Tzorah) era una ciudad en la Sefelá, a unos veinticuatro kilómetros al oeste de Jerusalén, asignada tanto a Judá (Jos 15:33) como a Dan (Jos 19:41). Es conocida sobre todo como el hogar de Manoa, padre de Sansón (Jue 13:2), y el lugar donde el Espíritu del SEÑOR comenzó a impulsar al joven Sansón (Jue 13:25). Sansón fue sepultado allí, entre Zora y Estaol (Jue 16:31). La ciudad también sirvió como punto de partida para los espías y la migración danita (Jue 18:2, 8, 11), y Roboam la fortificó posteriormente (2 Cr 11:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6882', 'spa', 'Zoratita/Zoreíta; gentilicios que identifican miembros de clanes asociados con Zora en Judá', 'Estos gentilicios relacionados identifican grupos de clanes conectados con Zora, una ciudad en el territorio tribal de Judá. Primera de Crónicas 2:53-54 y 4:2 enumeran a los zoratitas y zoreítas entre las familias de Judá descendientes de Sobal y líneas relacionadas. Las dos formas (zoratita/zoreíta) parecen designar los mismos grupos o grupos estrechamente relacionados de la región de Zora, aunque la relación textual permanece poco clara. El artículo definido (''los zoratitas'') marca estas como entidades colectivas conocidas dentro de la estructura genealógica de Judá. Esto es identificación genealógica y geográfica: nombres de clanes que derivan de nombres de lugares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6883', 'spa', 'tsara''at -- enfermedad cutánea ritualmente contaminante (también en vestiduras y casas) que requiere diagnóstico sacerdotal', 'tsara''at -- enfermedad cutánea ritualmente contaminante (también en vestiduras y casas) que requiere diagnóstico sacerdotal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6884', 'spa', 'Fundir, refinar, purificar; de la metalurgia y de Dios probando el carácter; como participio, orfebre o refinador', 'Fundir, refinar, purificar; de la metalurgia y de Dios probando el carácter; como participio, orfebre o refinador');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6885', 'spa', 'orfebre, metalúrgico (como designación gremial colectiva)', 'Este sustantivo designa a los orfebres o metalúrgicos como grupo colectivo o gremio profesional. Nehemías 3:31 menciona al «hijo de los orfebres», es decir, un miembro del gremio de orfebres. En la Jerusalén posterior al exilio, los artesanos se organizaban en gremios profesionales con fines económicos y sociales. La expresión indica pertenencia gremial, no descendencia biológica. El orfebre mencionado participaba en la reconstrucción de los muros de Jerusalén, lo que muestra cómo diversos gremios contribuyeron al proyecto de restauración, reflejando la estructura organizada de la comunidad artesanal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6886', 'spa', 'Sarepta; ciudad costera fenicia entre Sidón y Tiro, donde Elías se hospedó con una viuda', 'Sarepta era una ciudad costera fenicia al sur de Sidón donde Elías encontró refugio durante la sequía. Primera de Reyes 17:9-10 describe cómo Dios dirigió a Elías a ir a Sarepta, donde una viuda lo sostendría, lo que llevó a los milagros del aceite interminable y la resurrección del hijo de la viuda. Abdías 20 profetiza que los exiliados de Israel poseerán territorio fenicio ''hasta Sarepta''. El sitio se identifica con el moderno Sarafand en Líbano. La ciudad se convirtió en emblemática del cuidado de Dios que se extiende más allá de las fronteras de Israel, como Jesús recordó más tarde en Lucas 4:26.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6887', 'spa', 'angustiar, causar aflicción, estar en aprietos', 'Este verbo significa estar angustiado o causar angustia, y aparece en el conmovedor lamento de Lamentaciones 1:20, donde Jerusalén personificada clama: «mis entrañas se revuelven, mi corazón se trastorna dentro de mí, porque me rebelé gravemente». El verbo puede funcionar de forma transitiva (causar aflicción) o intransitiva (estar afligido). Aquí Jerusalén experimenta una angustia abrumadora, tanto emocional como física, reconociendo este sufrimiento como consecuencia de su rebeldía. El término transmite la idea de constricción, de verse apretado en estrecheces sin espacio para el alivio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6887b', 'spa', 'Atar, envolver; estar estrecho o en angustia; en Hifil, causar angustia o sitiar; en pasivo, estar atado o confinado', 'Atar, envolver; estar estrecho o en angustia; en Hifil, causar angustia o sitiar; en pasivo, estar atado o confinado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6887d', 'spa', 'Mostrar hostilidad, hostigar; como participio: un adversario, enemigo, quien oprime o angustia', 'Mostrar hostilidad, hostigar; como participio: un adversario, enemigo, quien oprime o angustia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6887e', 'spa', 'tomar como esposa rival, hacer coesposa', 'Este verbo denominativo significa hacer de alguien una esposa rival, es decir, tomar a una mujer como coesposa de otra. Levítico 18:18 lo emplea al prohibir que un hombre se case con la hermana de su esposa mientras esta viva, «para hacerla rival». La Torá reconoce el conflicto inherente en tales arreglos, prohibiendo esta configuración particular aun cuando la poligamia estaba permitida. La existencia misma de este verbo refleja la realidad social de los matrimonios polígamos y las dinámicas de rivalidad que producían, como se observa en la relación entre Ana y Penina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6888', 'spa', 'Zererah (topónimo en Israel, probablemente una lectura textual corrupta de Zaretán)', 'Este topónimo aparece únicamente en Jueces 7:22, donde se describe la huida de los madianitas tras la victoria de Gedeón. El texto indica que huyeron «hacia Zererah, hasta el borde de Abel-mejolá». La mayoría de los estudiosos considera que este nombre es una corrupción textual, y que originalmente debía leerse «Zaretán» o «Zereda», localidades conocidas. La Septuaginta ofrece una lectura notablemente distinta, lo que refleja una incertidumbre textual temprana. Pese a la lectura incierta, el nombre designa claramente un lugar en el valle del Jordán hacia el cual huyó el ejército madianita derrotado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6889', 'spa', 'Zéret (descendiente de Judá)', 'Este nombre personal aparece en 1 Crónicas 4:7 dentro de una lista genealógica de los descendientes de Judá. Más allá de su lugar en la genealogía, prácticamente no se conoce nada sobre este individuo. El nombre podría derivar de raíces que sugieren esplendor o brillo, aunque esto sigue siendo incierto. Tales registros genealógicos preservaban los vínculos tribales y familiares incluso cuando los datos biográficos individuales se habían perdido. Las extensas genealogías de Crónicas servían para mantener el sentido de identidad y continuidad de Israel a través del exilio y la restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6890', 'spa', 'Zéret-sahar (ciudad en el territorio de Rubén, posiblemente significa ''esplendor del alba'')', 'Este topónimo compuesto designa una ciudad perteneciente a la heredad tribal de Rubén, al este del mar Muerto. Josué 13:19 la incluye entre las ciudades asignadas a dicha tribu. El nombre podría significar «esplendor del alba» o «brillo de la mañana», quizá en alusión a las características del lugar. Se ha identificado tentativamente con la actual es-Sara, en una estribación del monte Atarús. Su ubicación habría formado parte de las tierras altas transjordanas con vistas al mar Muerto, un terreno caracterizado por panorámicas espectaculares y una luminosidad matutina singular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6891', 'spa', 'Saretán/Zartán; nombre de lugar en el Valle del Jordán, asociado con Jericó y la fundición de bronce para el templo', 'Saretán era un lugar en el Valle del Jordán con identificación precisa incierta. Josué 3:16 lo menciona como punto de referencia cuando las aguas del Jordán se detuvieron para el cruce de Israel: las aguas se represaron ''hasta Adam, cerca de Saretán''. Primera de Reyes 7:46 lo identifica como el área donde Hiram fundió objetos de bronce para el templo de Salomón (el pasaje paralelo de 2 Crónicas 4:17 tiene ''Zereda''). Primera de Reyes 4:12 lo incluye en una descripción de límites de distrito. El nombre aparece en formas variantes, y su sitio exacto permanece debatido, aunque en algún lugar del Valle del Jordán entre Adam y Sucot.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6892a', 'spa', 'Vómito, lo que se ha vomitado', 'Este sustantivo designa el vómito, es decir, lo que ha sido expulsado del estómago. Proverbios 26:11 lo emplea en una comparación memorable y deliberadamente repulsiva: «Como perro que vuelve a su vómito, así es el necio que repite su necedad». La imagen busca provocar rechazo para subrayar lo insensato que resulta volver a conductas destructivas. Así como el acto del perro es nauseabundo e irracional, también lo es la repetición de la necedad por parte del insensato. Este proverbio se hizo tan célebre que fue citado en 2 Pedro 2:22 para describir a falsos maestros que recaen en sus antiguas costumbres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6892b', 'spa', 'vómito; contenido estomacal expulsado, usado literal y metafóricamente para resultados repulsivos de exceso o juicio', 'Este sustantivo se refiere al vómito: contenido estomacal expulsado. Isaías 28:8 describe mesas llenas de vómito e inmundicia, representando a sacerdotes y profetas ebrios cuyo exceso conduce al disgusto. Isaías 19:14 lo usa en un símil: Egipto se tambalea ''como un borracho en su vómito'', incapaz de encontrar dirección. Jeremías 48:26 ordena que Moab ''se revuelque en su vómito'', experimentando humillación como juicio. La imagen es deliberadamente repulsiva, representando las consecuencias de la embriaguez (literal o metafórica) y el juicio divino que deja a las naciones en desgracia. La evidencia interlingüística traduce consistentemente como vómito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6893', 'spa', 'Pelícano o búho del desierto; ave impura que habita ruinas desoladas y parajes yermos', 'Ave impura incluida entre las especies prohibidas en Levítico 11:18 y Deuteronomio 14:17. Su identificación es debatida: las versiones antiguas suelen traducirla como ''pelícano'' (así el griego y el latín del Salmo 102:6), pero su asociación con ruinas desiertas en Isaías 34:11 y Sofonías 2:14 ha llevado a muchos estudiosos modernos a identificarla como una especie de búho o avetoro. El Salmo 102:6 la emplea como imagen conmovedora de soledad desoladora: ''Soy semejante al pelícano del desierto.'' El español traduce consistentemente ''pelícano,'' mientras que las traducciones inglesas oscilan entre ''pelican'' y ''desert owl.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6894', 'spa', 'Cab, medida de capacidad para áridos equivalente a aproximadamente 2 litros, un sexto de sea', 'El cab era una unidad de medida hebrea utilizada para productos secos. Según BDB, equivalía a cuatro log o a un sexto de sea, lo que corresponde aproximadamente a 2 litros en términos modernos. La palabra aparece una sola vez en las Escrituras, durante el terrible asedio de Samaria, cuando la escasez de alimentos llegó a tal extremo que incluso un cuarto de cab de estiércol de paloma se vendía por plata. Este detalle tan crudo ilustra con fuerza la desesperación de las condiciones de hambruna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6895', 'spa', 'Proferir una maldición contra alguien; pronunciar una imprecación, especialmente en la narrativa de Balaam.', 'A diferencia de otros verbos hebreos para maldecir como אָרַר y קָלַל, esta raíz (קָבַב) conlleva el sentido de invocar una imprecación formal y hablada contra una persona. Domina el ciclo de Balaam en Números 22-24, donde Balac repetidamente ordena a Balaam maldecir a Israel, solo para que Dios transforme cada intento en bendición. El español ''maldecir'' resalta la dimensión de acto de habla: se trata de una declaración performativa, no un mero deseo de daño. Job 3:8 lo extiende a quienes maldicen el día, posiblemente encantadores profesionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6896', 'spa', 'El estómago o cuarto compartimento estomacal de un animal rumiante destinado al sacrificio', 'Se refiere específicamente al estómago de los animales sacrificiales, en particular al cuarto compartimento (abomaso) de los rumiantes. Deuteronomio 18:3 establece que esta porción debía entregarse a los sacerdotes como parte de su derecho sobre las ofrendas de animales. Las versiones antiguas como la Septuaginta lo traducen como «el estómago interior», reconociendo su uso técnico dentro del sistema cúltico. La forma hebrea lleva el artículo definido prefijado, indicando «el estómago» como una porción sacerdotal reconocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6897', 'spa', 'Vientre o abdomen, referido a una mujer en un contexto de muerte violenta', 'Aunque comparte la misma raíz que H6896, esta forma aparece con un sufijo femenino de tercera persona («su vientre») y tiene un sentido anatómico más general. En Números 25:8, la lanza de Finees atraviesa tanto al hombre israelita como a la mujer madianita «por el vientre de ella», un detalle gráfico que subraya el celo y la violencia de su intervención. La evidencia multilingüe favorece la traducción «vientre» sobre el más técnico «estómago», lo que sugiere una referencia anatómica amplia más que un término cúltico específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6898', 'spa', 'Tienda grande abovedada o pabellón, posiblemente usada como morada o con fines inmorales', 'Esta palabra poco frecuente designa un tipo de tienda, descrita específicamente como grande y abovedada. Aparece en el mismo relato de Finees (Números 25:8), refiriéndose a la estructura donde el israelita llevó a la mujer madianita. Algunos intérpretes sugieren que era una tienda principesca acorde con el rango de Zimri; otros proponen que servía como lugar de prostitución, citando paralelos en el hebreo posterior. La especificidad arquitectónica («abovedada») la distingue de las tiendas comunes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6899', 'spa', 'Conjunto, colección o masa reunida (especialmente de ídolos)', 'Este sustantivo denota una agrupación o conjunto de cosas. Isaías 57:13 emplea la forma plural posesiva para burlarse de los idólatras: «¡Que tu colección [de ídolos] te libre!». El sarcasmo del profeta apunta a la multiplicidad de dioses inútiles acumulados. Algunos estudiosos textuales señalan que ciertos manuscritos leen «tus abominaciones» en su lugar, aunque el sentido de falsos dioses acumulados se mantiene. Algunos traductores al francés dejaron el hebreo sin traducir, indicando incertidumbre textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6900', 'spa', 'Sepultura o entierro; tumba donde alguien es depositado para su descanso final, o el acto mismo de dar sepultura. Se refiere tanto al lugar físico del', 'Sepultura o entierro; tumba donde alguien es depositado para su descanso final, o el acto mismo de dar sepultura. Se refiere tanto al lugar físico del entierro —una tumba, sepulcro o fosa— como al acto de sepultar como rito. La palabra aparece frecuentemente con sufijos posesivos (''su sepultura'', ''su tumba''), subrayando la importancia personal y familiar de un entierro apropiado en el antiguo Israel. La tumba de Raquel (Gn 35:20) se convirtió en un hito memorable, mientras que la mordaz expresión de Jeremías ''sepultura de asno'' (Jer 22:19) transforma el concepto en una poderosa imagen de deshonra. La distinción entre lugar y acto es sutil pero real: el contexto y la evidencia multilingüe (español sepultura vs. sepulcro; francés tombeau vs. el sentido abstracto) ayudan a delimitar la frontera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6901', 'spa', 'Recibir o aceptar algo ofrecido; también (Hifil) estar en correspondencia, hallarse uno frente al otro. Préstamo del arameo incorporado al hebreo tard', 'Recibir o aceptar algo ofrecido; también (Hifil) estar en correspondencia, hallarse uno frente al otro. Préstamo del arameo incorporado al hebreo tardío, este verbo abarca tanto el acto de recibir cosas tangibles (sangre, vasijas, plata) como la aceptación voluntaria de obligaciones o compromisos. En Job 2:10, Job pregunta si debemos recibir lo bueno de Dios pero no lo malo, una pregunta que resuena a lo largo de todas las tradiciones de traducción. Una forma Hifil más rara aparece en Éxodo 26:5 y 36:12 describiendo los lazos del tabernáculo que ''se corresponden'' entre sí, preservando el sentido espacial original de la raíz aramea: estar cara a cara, en posición opuesta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6902', 'spa', 'recibir; aceptar o tomar posesión de algo, particularmente recompensas o reino (arameo)', 'Este verbo arameo significa recibir o tomar posesión de algo. Daniel 2:6 promete que los intérpretes del sueño del rey recibirán regalos y recompensas. Daniel 5:31 (arameo 6:1) declara que Darío el medo recibió el reino. Daniel 7:18 profetiza que los santos del Altísimo recibirán el reino para siempre. El rango semántico cubre tanto la recepción material (regalos) como la adquisición política (reino). La forma Piel enfatiza el acto de recibir, con contextos que sugieren tanto el otorgamiento humano como la concesión divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6903', 'spa', 'Preposición aramea: a causa de, por motivo de (causal); también delante de, enfrente de (espacial/locativo).', 'Preposición aramea: a causa de, por motivo de (causal); también delante de, enfrente de (espacial/locativo).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6904', 'spa', 'Ariete o máquina de asedio empleada en la guerra de sitio', 'Este término militar se refiere al equipo de asedio, específicamente a una máquina diseñada para golpear murallas. Ezequiel 26:9 describe el ataque de Nabucodonosor contra Tiro: «el golpe de su ariete» se dirigirá contra las defensas de la ciudad. La raíz hebrea se relaciona con raíces semíticas que significan «frente» o «avanzar», captando la naturaleza de empuje frontal de la maquinaria de asedio. La forma morfológica conserva un patrón arcaico, lo que sugiere vocabulario militar antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6906', 'spa', 'Robar, despojar o defraudar; usado especialmente para retener lo que se le debe a Dios.', 'Un verbo que significa robar, despojar o defraudar, sinónimo de gazal. Su aparición más célebre es Malaquías 3:8 — ''¿Robará el hombre a Dios?'' — donde se acusa a Israel de robar al SEÑOR al retener los diezmos y las ofrendas. Ese pasaje concentra cuatro de las seis apariciones del vocablo en una sola confrontación entre Dios y su pueblo. En Proverbios 22:23, el SEÑOR mismo se convierte en quien ''despoja'' a los que despojan al pobre, volviendo el verbo contra el opresor. Las traducciones en español emplean ''robáis'' y el alemán ''beraubt'', ambas captan la franqueza de la acusación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6908', 'spa', 'Reunir, congregar, juntar; Piel: reagrupar a los dispersos; Nifal: congregarse; Qal: recoger', 'קָבַץ es uno de los dos grandes verbos hebreos de reunión (junto con אָסַף), y su fuerza particular reside en la reagrupación de lo que ha sido dispersado. Mientras que אָסַף suele implicar recolección hacia un punto fijo —cosechar, ser reunido con los padres al morir—, קָבַץ conlleva el matiz dramático de recuperación y restauración, especialmente del Israel exiliado. La fórmula profética ''os reuniré de entre las naciones'' (Ez 11:17; 20:34, 41; 36:24) emplea el Piel de קָבַץ casi en exclusiva, convirtiéndolo en verbo definitorio de la esperanza escatológica. El sistema de conjugaciones distribuye la semántica con elegancia: el Qal maneja la recolección transitiva directa, el Piel la intensifica en reagrupación deliberada, y el Nifal/Hitpael marca la dimensión reflexivo-recíproca donde el pueblo se congrega por sí mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6909', 'spa', 'Cabseel; ciudad en el sur de Judá, hogar de Benaía el valiente guerrero', 'Cabseel era una ciudad en la región del sur (Neguev) del territorio de Judá. Josué 15:21 la incluye entre las ciudades más meridionales de Judá. Segundo Samuel 23:20 y su paralelo en 1 Crónicas 11:22 la identifican como la ciudad natal de Benaía hijo de Joiada, uno de los guerreros de élite de David que luego se convirtió en comandante del ejército de Salomón. El nombre puede significar ''Dios reúne'' o ''reunión de Dios''. Su ubicación exacta es incierta, aunque fue repoblada después del exilio (Nehemías 11:25). La ciudad es recordada principalmente por las hazañas heroicas de Benaía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6912', 'spa', 'Sepultar a un difunto en tumba o sepulcro; en voz pasiva, ser sepultado; por extensión, el que sepulta', 'קָבַר es el verbo hebreo universal para la inhumación de los muertos; aparece en todas las conjugaciones y recorre la narrativa bíblica entera, desde la compra de la cueva de Macpela por Abraham (Gn 23) hasta el valle apocalíptico de sepultura masiva de Ezequiel (Ez 39). Su núcleo semántico es extraordinariamente estable entre lenguas semíticas: el árabe qabara, el arameo qebar y el acadio qibiru conservan la misma raíz con idéntico significado. Lo que varía según la conjugación es la agencia y la intensidad: el Qal describe el acto directo de sepultar, el Nifal y el Pual marcan el estado honroso o deshonroso de ser sepultado, y el Piel intensifica la acción hacia un enterramiento sistemático o masivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6913', 'spa', 'qever — sepulcro, tumba o lugar de sepultura; el lugar donde se entierra un cadáver.', 'qever — sepulcro, tumba o lugar de sepultura; el lugar donde se entierra un cadáver.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6914', 'spa', 'Quibrot-Hataava; ''sepulcros de la codicia,'' campamento israelita en el desierto', 'Nombre compuesto de lugar que significa ''sepulcros de la codicia'' o ''tumbas del deseo,'' señalando una estación en el itinerario israelita por el desierto. Números 11:34 explica su etimología: el pueblo que codicló carne fue sepultado allí tras el juicio de Dios mediante una plaga. El nombre aparece en la narración de viaje (Nm 11:34-35; 33:16-17) y en la rememoración que hace Moisés de las rebeliones de Israel (Dt 9:22). Las principales traducciones transliteran el nombre en vez de traducirlo, como confirman el español ''Quibrot-Hataava'' y el francés ''Kibroth-hattaavah.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6915', 'spa', 'Inclinar la cabeza, arrodillarse en reverencia o sumisión; se usa para la adoración ante Dios y el homenaje ante reyes. El verbo qādad describe el act', 'Inclinar la cabeza, arrodillarse en reverencia o sumisión; se usa para la adoración ante Dios y el homenaje ante reyes. El verbo qādad describe el acto físico de inclinar profundamente la cabeza o arrodillarse hacia adelante, casi siempre emparejado con el más frecuente hishtaḥăwâ (''postrarse'') en una endíadis de adoración u homenaje. El siervo de Abraham se inclina y adora cuando encuentra a Rebeca (Gn 24:26, 48); Israel se inclina ante la noticia de la liberación de Egipto (Éx 4:31; 12:27); Betsabé se inclina ante el rey David (1 R 1:16, 31). La combinación aparece con tanta regularidad que qādad parece designar la inclinación inicial de la cabeza y la parte superior del cuerpo, mientras que hishtaḥăwâ completa la postración plena. El español ''se inclinó'' y el inglés ''bowed down'' captan fielmente este movimiento reverente e inicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6918', 'spa', 'Sagrado, santo; consagrado a Dios; como título divino, ''el Santo''; en plural, los santos o seres celestiales', 'קָדוֹשׁ es el adjetivo en el corazón de la teología bíblica: la palabra que los serafines de Isaías proclaman tres veces (Is 6:3) y la que define la vocación de Israel: ''Sed santos, porque yo, el SEÑOR vuestro Dios, soy santo'' (Lv 19:2). Su significado raíz es separación o apartamiento, pero en el uso bíblico esa separación nunca es mero aislamiento, sino consagración hacia Dios, cargada de presencia divina y exigencia moral. Como atributo divino, קָדוֹשׁ describe la alteridad trascendente de Dios. Como título, ''el Santo de Israel'' (קְדוֹשׁ יִשְׂרָאֵל) se convierte en la designación emblemática de Isaías para Dios, fundiendo trascendencia con intimidad pactual. El plural קְדוֹשִׁים abarca tanto a seres angélicos del consejo celestial como a seres humanos llamados a reflejar la santidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6919', 'spa', 'Encender, encenderse; prender fuego, especialmente referido a la ira divina que arde como llama', 'Verbo que significa encender o ser encendido, con una marcada asociacion con la ira divina. En Deuteronomio 32:22 se establece la expresion teologica clave: ''un fuego se ha encendido en mi ira'', formula repetida en Jeremias 15:14 y 17:4. Isaias 64:2 emplea el infinitivo en un simil que compara la teofania de Dios con fuego que enciende la hojarasca, mientras que Isaias 50:11 advierte a quienes encienden su propio fuego. La raiz cognada arabe remite al acto concreto de producir fuego golpeando pedernal, anclando el termino en la accion fisica de provocar llama.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6921', 'spa', 'El oriente como punto cardinal o marcador de fronteras; también el abrasador viento del este (siroco) proveniente del desierto, a menudo instrumento d', 'El oriente como punto cardinal o marcador de fronteras; también el abrasador viento del este (siroco) proveniente del desierto, a menudo instrumento de juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6922', 'spa', 'Santo, sagrado (arameo); usado en Daniel para referirse a Dios, a los vigilantes angélicos y a los escatológicos ''santos del Altísimo''. El equivalente', 'Santo, sagrado (arameo); usado en Daniel para referirse a Dios, a los vigilantes angélicos y a los escatológicos ''santos del Altísimo''. El equivalente arameo del hebreo קָדוֹשׁ, que aparece exclusivamente en Daniel. Describe al espíritu divino dentro de los consejeros de Nabucodonosor como ''el espíritu de los dioses santos'' (Dn 4:5–6, 15; 5:11), al ''vigilante'' angélico que desciende del cielo (Dn 4:10, 14, 20) y —de manera más trascendental— a los קַדִּישֵׁי עֶלְיוֹנִין, ''santos del Altísimo'', quienes reciben un reino eterno (Dn 7:18, 22, 25, 27). El español lo traduce como santos, el alemán como heilig, y su peso teológico es enorme: este único adjetivo tiende un puente entre el cielo y la tierra en la visión apocalíptica de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6923', 'spa', 'Salir al frente, encontrar, confrontar; en Piel, anticipar o preceder; en Hifil, dar de antemano.', 'Salir al frente, encontrar, confrontar; en Piel, anticipar o preceder; en Hifil, dar de antemano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6924a', 'spa', 'Oriente o dirección oriental; tiempo antiguo o antigüedad; delante de o antes de, en sentido espacial o temporal.', 'Oriente o dirección oriental; tiempo antiguo o antigüedad; delante de o antes de, en sentido espacial o temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6924b', 'spa', 'Hacia el oriente, en dirección al este — forma adverbial direccional que indica orientación o movimiento hacia el amanecer.', 'Hacia el oriente, en dirección al este — forma adverbial direccional que indica orientación o movimiento hacia el amanecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6925', 'spa', 'Delante de, en presencia de; preposición aramea que indica presencia espacial o (raramente) anterioridad temporal', 'Delante de, en presencia de; preposición aramea que indica presencia espacial o (raramente) anterioridad temporal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6926', 'spa', 'al este de, delante de (uso preposicional que indica dirección o ubicación geográfica oriental)', 'Frase preposicional que significa «al este de» o «delante de», derivada de la raíz que denota «antes» u «oriente». Génesis 2:14 sitúa el Tigris «al este de» Asiria, reflejando la perspectiva occidental del narrador. Génesis 4:16 indica que Caín habitó «al este de Edén». 1 Samuel 13:5 ubica el campamento filisteo «al este de» Bet-avén. Ezequiel 39:11 describe el Valle de los Transeúntes «al este del mar». El término marca orientación geográfica, generalmente hacia el este desde un punto de referencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6927', 'spa', 'Estado anterior, condición previa; origen o principio; ''antes'' temporal (con influencia aramea)', 'Derivado de la raíz q-d-m (''frente, oriente, antiguo''), qadmah designa lo que existió antes, ya sea una condición previa a la cual algo puede retornar, o el origen y principio mismo de una cosa. Ezequiel lo emplea repetidamente en promesas de restauración: Sodoma y Samaria volverán a su ''estado anterior'' (Ezek 16:55), e Israel será restituido mejor que en sus ''tiempos anteriores'' (Ezek 36:11). Isaías 23:7 lo aplica al origen antiguo de Tiro. En el Salmo 129:6, la forma constructa funciona casi como conjunción temporal con el sentido de ''antes'', un aramaísmo que refleja la flexibilidad temporal de este vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6931', 'spa', 'Anterior o antiguo (temporal); oriental (direccional). Adjetivo que une la prioridad temporal con la orientación espacial.', 'El adjetivo קַדְמֹנִי se divide entre dos polos semánticos: ''oriental'' en contextos geográficos y ''anterior/antiguo'' en los temporales, ambos derivados de la raíz קדם, cuya noción básica es ''frente'' o ''delante''. Dado que la orientación israelita situaba el este como la dirección hacia la que uno mira, ''delante de'' produjo tanto ''hacia el oriente'' como ''anterior en el tiempo''. Ezequiel usa el término para la puerta oriental del templo (Ez 10:19; 11:1) y el mar oriental, es decir, el Mar Muerto (Ez 47:18). En el plano temporal, Isaías 43:18 insta a Israel a no recordar las ''cosas anteriores'', y Malaquías 3:4 evoca los ''años antiguos''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6932', 'spa', 'Quedemot (nombre de lugar, ciudad levítica en territorio de Rubén/Moab con desierto asociado)', 'Ciudad levítica en territorio de Rubén, originalmente moabita, con un desierto asociado. Deuteronomio 2:26 menciona el «Desierto de Quedemot», desde donde Moisés envió mensajeros de paz a Sehón. Josué 13:18 la incluye entre las ciudades de Rubén. Josué 21:37 y 1 Crónicas 6:79 la identifican como ciudad levítica. El sitio se encuentra al norte del alto Arnón, pero no ha sido identificado arqueológicamente con certeza. El nombre deriva de la raíz que significa «oriente» o «antiguo», posiblemente «lugar oriental» o «sitio antiguo».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6933', 'spa', 'anterior, primero; lo que vino antes en el tiempo o secuencia (arameo)', 'Este adjetivo arameo significa anterior o primero, refiriéndose a lo que vino antes. Daniel 7:4, 8, 24 lo usan en la visión de las bestias y los cuernos. Se describe la ''primera'' bestia, distinguiéndola de las que siguen. Los ''cuernos anteriores'' (7:8, 24) son aquellos que precedieron al surgimiento del cuerno pequeño. El término provee ordenamiento temporal o secuencial en material visionario, ayudando a seguir la sucesión de reinos y poderes. Gramaticalmente, aparece en varias formas (femenino singular enfático, femenino/masculino plural enfático) concordando con los sustantivos que modifica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6934', 'spa', 'Cadmiel — ''El es el antiguo''; líder levita destacado en el culto y la renovación del pacto de la comunidad postexílica.', 'Cadmiel es un nombre levítico que significa «Dios es el antiguo» o «El es desde la antigüedad», combinando qedem (''oriente, tiempo antiguo'') con El. Este líder levita aparece en cada hito importante de la restauración postexílica: entre los exiliados que retornaron (Esd 2:40 = Neh 7:43), supervisando la reconstrucción del Templo bajo Zorobabel (Esd 3:9), dirigiendo la adoración pública y la confesión (Neh 9:4-5), sellando la renovación del pacto (Neh 10:10) y sirviendo en labores de alabanza y acción de gracias (Neh 12:8, 24). La teología de su nombre, que afirma la prioridad eterna de Dios, resuena con el esfuerzo de la comunidad por restablecer el culto ancestral en una nueva era.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6936', 'spa', 'Coronilla, parte superior del cráneo; la cima de la cabeza, frecuente en bendiciones y maldiciones', 'Designa la parte más alta de la cabeza — el punto donde descienden las bendiciones y golpean las aflicciones. La bendición de Jacob pronuncia favor sobre la «coronilla» de José, el consagrado entre sus hermanos (Gn 49:26; cf. Dt 33:16). Por el contrario, Deuteronomio 28:35 advierte sobre úlceras desde la planta del pie hasta la coronilla. La palabra conlleva un matiz casi regio: el punto más elevado del cuerpo humano se convierte en símbolo de dignidad o vulnerabilidad. El español «coronilla» conserva fielmente esta imagen de pequeña corona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6937', 'spa', 'Oscurecerse, estar de luto en tinieblas, o causar oscuridad; de cielos que se ennegrecen, personas que se lamentan, o Dios oscureciendo los cielos. קָ', 'Oscurecerse, estar de luto en tinieblas, o causar oscuridad; de cielos que se ennegrecen, personas que se lamentan, o Dios oscureciendo los cielos. קָדַר se mueve entre el oscurecimiento literal de los cielos y la oscuridad emocional del duelo. Cuando el siervo de Elías vio los cielos ennegrecerse con nubes (1 R 18:45), el mismo verbo describía la escena como cuando Jeremías caminaba en tinieblas bajo el peso del dolor profético (Jer 8:21). En Ezequiel, Dios mismo se convierte en el agente que oscurece el sol y las estrellas en juicio — una intensificación causativa del sentido intransitivo básico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6938', 'spa', 'Quedar — segundo hijo de Ismael; por extensión, poderosa tribu árabe nómada famosa por sus tiendas negras y rebaños', 'Quedar (קֵדָר) nombra al segundo hijo de Ismael (Gn 25:13; 1 Cr 1:29) y a la tribu árabe nómada descendiente de él en el desierto sirio-arábigo. Célebres por sus tiendas de pelo de cabra negra, la amada compara su belleza morena con «las tiendas de Quedar» (Cnt 1:5), mientras el salmista lamenta habitar entre ellos como exilio hostil (Sal 120:5). Isaías profetiza la decadencia de Quedar (Is 21:16-17), pero también vislumbra sus rebaños confluyendo hacia Jerusalén (Is 60:7). Jeremías registra la campaña de Nabucodonosor contra Quedar (Jer 49:28), y Ezequiel los menciona entre los socios comerciales de Tiro (Ez 27:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6939', 'spa', 'Cedrón, el valle-torrente al este de Jerusalén, usado para deshacerse de objetos idolátricos', 'Nombre del profundo valle que corre entre la muralla oriental de Jerusalén y el Monte de los Olivos, por el cual fluye un arroyo estacional. David cruzó el Cedrón llorando cuando huía de Absalón (2 S 15:23), y Salomón advirtió a Simei que cruzarlo significaría la muerte (1 R 2:37). Los reyes reformadores quemaron repetidamente ídolos y objetos de culto allí (1 R 15:13; 2 R 23:4), convirtiendo al Cedrón en un límite recurrente entre la ciudad santa y sus impurezas rechazadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6942', 'spa', 'Ser santo, santificar, consagrar, apartar como sagrado; declarar o hacer santo en Qal, Piel, Hifil, Hitpael, Nifal y Pual', 'Verbo fundacional del concepto bíblico de santidad, que recorre todas las conjugaciones principales del hebreo para expresar el espectro completo de llegar a ser, hacer y ser declarado sagrado. En el Piel, Dios santifica el sábado (Gn 2:3) e Israel consagra sacerdotes y altares. El Hitpael llama al individuo a purificarse antes del encuentro divino, mientras que el Nifal revela a Dios mostrándose santo entre las naciones. El árabe قَدَّسَ y el suajili -takasa reflejan la misma raíz semítica, subrayando el peso ancestral y transcultural de apartar algo para lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6943', 'spa', 'Cedes — ciudad de refugio en Neftalí; también ciudades en Isacar y el sur de Judá; significa «santuario»', 'Cedes (קֶדֶשׁ), que significa «santuario», designa hasta tres ciudades israelitas. La más prominente es Cedes en Neftalí, una ciudad cananea conquistada (Jos 12:22) designada como ciudad de refugio (Jos 20:7) y ciudad levítica gersonita (Jos 21:32; 1 Cr 6:61). Barac hijo de Abinoam era de Cedes, donde Débora lo convocó para luchar contra Sísara (Jue 4:6, 9-10). Tiglat-pileser III la capturó durante la conquista asiria de Galilea (2 R 15:29). Una segunda Cedes en Isacar (1 Cr 6:57) y una tercera en el sur de Judá (Jos 15:23) comparten el mismo nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6944', 'spa', 'Santidad, sacralidad, santuario, cosa santa; el estado de estar apartado para Dios o el lugar, objeto u ofrenda consagrados', 'El sustantivo קֹדֶשׁ ancla todo el vocabulario bíblico de lo sagrado. Edificado sobre la idea raíz de separación, nombra tanto la cualidad abstracta de santidad como toda realidad concreta tocada por ella — desde el suelo ardiente ante Moisés hasta la cámara más recóndita del templo. En la construcción superlativa קֹדֶשׁ קָדָשִׁים (''santo de los santos''), la gramática hebrea misma se intensifica para marcar la frontera entre lo accesible y lo inaccesible. El árabe مَقْدِس y los cognados semíticos confirman que los sentidos espacial y cualitativo nunca estuvieron realmente separados: ser santo es estar apartado, y el lugar santo es donde esa separación se vuelve más tangible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6945', 'spa', 'Prostituto cultual masculino; hombre dedicado a prácticas sexuales rituales en santuarios paganos, condenado en la ley deuteronómica.', 'Designa a un prostituto cultual masculino, un hombre consagrado a prácticas sexuales rituales en santuarios cananeos o sincretistas. La Escritura condena esta figura consistentemente en la historia deuteronomista: la ley prohíbe que cualquier israelita se convierta en qadesh (Deut 23:17), y los reyes reformadores son elogiados por eliminarlos de la tierra (1 Kgs 15:12; 22:46; 2 Kgs 23:7). El reinado de Roboam, en cambio, se caracteriza por la presencia de qedeshim en la tierra (1 Kgs 14:24). Job 36:14 advierte que los impíos mueren ''entre los qedeshim'', sugiriendo un final ignominioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6946', 'spa', 'Cades — un sitio sagrado en el desierto del Néguev donde Israel acampó durante las peregrinaciones del éxodo. Significa ''sagrado'' o ''lugar santo''; Cad', 'Cades — un sitio sagrado en el desierto del Néguev donde Israel acampó durante las peregrinaciones del éxodo. Significa ''sagrado'' o ''lugar santo''; Cades (también llamado Cades-barnea) fue una parada principal en los viajes de Israel por el desierto, situado en el desierto de Zin cerca de la frontera de Edom. Sirvió como base desde la cual fueron enviados los doce espías a Canaán (Nm 13:26) y donde murió Miriam y Moisés golpeó la roca en Meriba (Nm 20:1-13). El sitio aparece a lo largo del Pentateuco, en Jueces, Salmos y en las descripciones de los límites ideales de Ezequiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6947', 'spa', 'Cades-Barnea; oasis importante y campamento en el desierto al sur de Canaán, clave en las narrativas de la peregrinación de Israel.', 'Cades-Barnea fue el punto de parada más significativo durante los cuarenta años de Israel en el desierto, sirviendo como base para el intento fallido de entrar en Canaán y como campamento prolongado. Desde aquí fueron enviados los doce espías (Nm 13:26), y aquí permaneció Israel ''muchos días'' tras el juicio divino (Dt 1:46). Figura prominentemente en las descripciones de los límites de la Tierra Prometida (Nm 34:4; Jos 15:3) y marca la distancia desde Horeb: once jornadas de camino (Dt 1:2). Los treinta y ocho años entre Cades-Barnea y el cruce del Zered definieron la peregrinación de toda una generación (Dt 2:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6948', 'spa', 'Prostituta cultual (femenino); mujer consagrada a ritos sexuales en un santuario pagano', 'Forma femenina de un sustantivo que designa a una persona consagrada a ritos sexuales culticos en un santuario pagano. En Genesis 38:21-22 Tamar es confundida con una prostituta del templo junto al camino, y Deuteronomio 23:17 prohibe a las hijas de Israel ejercer esa funcion. Oseas 4:14 condena a los hombres que se juntan con prostitutas cultuales. La conexion etimologica con קדשׁ (''santo'') revela una ironia profunda: lo que la religion cananea llamaba ''consagrado'' a una deidad, la ley israelita lo condenaba como abominacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6949', 'spa', 'embotarse, perder el filo (del metal); dar dentera (de los dientes por alimento ácido)', 'Verbo con dos aplicaciones: que el metal se vuelva romo o sin filo, y que los dientes sufran «dentera» (la sensación desagradable al comer alimento ácido). Eclesiastés 10:10 lo usa para un instrumento de hierro embotado que exige más esfuerzo. Jeremías 31:29-30 y Ezequiel 18:2 citan el proverbio «los padres comieron uvas agrias y a los hijos les dio dentera», que ambos profetas rechazan expresamente, enseñando responsabilidad individual en lugar de generacional por el pecado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6950', 'spa', 'Congregar, reunir -- en Hifil haciendo que otros se convoquen; en Nifal, reuniéndose como cuerpo', 'Congregar, reunir -- en Hifil haciendo que otros se convoquen; en Nifal, reuniéndose como cuerpo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6951', 'spa', 'Asamblea, congregación o compañía reunida; la comunidad convocada de Israel o cualquier gran grupo congregado', 'Derivado de la raíz ק-ה-ל (''congregar''), este sustantivo porta el peso de la identidad comunitaria en el antiguo Israel. Es la asamblea convocada para el culto, la ley y la guerra — la congregación que escucha la lectura pública de la Torá (Dt 31:30) y que se presenta ante Yahvé en el Sinaí. El francés assemblée y el alemán Versammlung marcan consistentemente el carácter formal y convocado de esta reunión. En contextos proféticos (Jer 50:9; Ez 17:17; 38:4), la palabra se amplía para describir confederaciones hostiles de naciones congregadas para la invasión, donde el matiz de ''multitud, hueste'' se distingue claramente de la asamblea sacra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6953', 'spa', 'Qohélet — ''el Predicador'' o ''el que convoca''; título del autor-orador en Eclesiastés.', 'Un título que significa «el que convoca una asamblea» o «el que recopila», traducido tradicionalmente como «el Predicador» (siguiendo el concionator de Jerónimo y el griego Ekklesiastes). Su morfología femenina probablemente indica un cargo o función, no género, de modo análogo al árabe khalifa (''califa''). Se usa exclusivamente en Eclesiastés (1:1, 2, 12; 7:27; 12:8, 9, 10) para identificar al orador del libro, presentado como un sabio real en Jerusalén. Si el énfasis recae en congregar personas o en recopilar dichos sapienciales es un debate que persiste desde la antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6955', 'spa', 'Coat -- segundo hijo de Leví, antepasado del clan levítico coatita encargado de transportar los objetos sagrados', 'Coat -- segundo hijo de Leví, antepasado del clan levítico coatita encargado de transportar los objetos sagrados');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6956', 'spa', 'Coatita — gentilicio para un descendiente de Coat, segundo hijo de Leví, uno de los tres clanes levíticos. Derivado del nombre propio Coat (קְהָת), es', 'Coatita — gentilicio para un descendiente de Coat, segundo hijo de Leví, uno de los tres clanes levíticos. Derivado del nombre propio Coat (קְהָת), este adjetivo gentilicio identifica a los miembros de uno de los tres grandes clanes levíticos. Los coatitas tenían la responsabilidad más sagrada entre los levitas: transportar el arca y los utensilios santos durante las travesías de Israel por el desierto (Nm 4:4-15). Su papel elevado hacía que la cercanía al tabernáculo fuera tanto un privilegio como un peligro, como lo atestigua la célebre advertencia de Números 4:18-20. El español lo traduce como ''coatita/quehatita'', mientras que el inglés usa consistentemente ''Kohathite(s)''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6957', 'spa', 'línea, cordel de medir; cuerda usada para medición, particularmente en construcción o agrimensura', 'Este sustantivo se refiere a una línea o cordel de medir, una herramienta para determinar dimensiones. Primero Reyes 7:23 menciona dos veces la línea usada para medir la circunferencia del mar de bronce en el templo de Salomón: ''un cordel de treinta codos lo rodeaba''. Jeremías 31:39 profetiza que un cordel de medir saldrá sobre Jerusalén en su futura restauración. La palabra aparece en contextos de construcción y proféticos, representando tanto medición práctica como actos simbólicos de construcción o restauración. Algunas ocurrencias tienen notas textuales (variaciones Ketiv-Qere), reflejadas en glosas entre corchetes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6957a', 'spa', 'Línea, cordel de medir; en Isaías 28, repetición burlona (''regla sobre regla'') imitando la instrucción profética.', 'Un sustantivo que significa «línea» o «cordel de medir», esta forma aparece exclusivamente en Isaías 28:10 y 28:13 en la frase repetida qav laqav, «regla sobre regla». La expresión captura el tono burlón de los escarnecedores que ridiculizan la enseñanza profética de Isaías como instrucción tediosa y repetitiva, propia de niños. Si las sílabas son hebreo genuino o un balbuceo deliberadamente distorsionado sigue siendo objeto de debate, pero la evidencia multilingüe refleja de manera uniforme la idea de un estándar de medida o regla aplicada de forma incremental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6957b', 'spa', 'Línea o cordel de medir; usado literalmente para construcción y agrimensura, y figuradamente para el juicio divino o la creación.', 'Se refiere a un cordel o línea tendida para medir, ya sea en construcción, delimitación de fronteras o acción divina. En contextos de construcción, el mar de bronce de Salomón medía treinta codos de circunferencia con un cordel (1 R 7:23; 2 Cr 4:2), y Ezequiel contempla a un ángel midiendo con una línea (Ez 47:3). La imagen se vuelve poderosamente figurada cuando Dios ''tiende un cordel'' sobre una ciudad, a veces para edificar (Zac 1:16), a veces para destruir (2 R 21:13; Lm 2:8; Is 34:11). Job 38:5 presenta la creación misma como un acto de agrimensura cósmica: ''¿Quién tendió sobre ella un cordel?''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6958', 'spa', 'Vomitar, arrojar, expulsar; usado literalmente y como poderosa metáfora de la tierra expulsando a sus habitantes.', 'Este verbo significa vomitar o expulsar con fuerza, y posee una intensidad visceral tanto en sus usos literales como figurados. En el Código de Santidad (Lv 18:25, 28; 20:22), la tierra misma es personificada como si vomitara a sus habitantes a causa de su contaminación moral, una imagen impactante que presenta la tierra como un cuerpo vivo que rechaza la impureza. La misma raíz aparece en Jonás 2:11, donde el gran pez vomita al profeta, y en Job 20:15, donde las riquezas mal habidas son devueltas por vómito. Las traducciones multilingües confirman el núcleo semántico constante de expulsión forzosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6960a', 'spa', 'Esperar, confiar con esperanza; como participio, los que esperan en Dios con paciente confianza', 'Esperar, confiar con esperanza; como participio, los que esperan en Dios con paciente confianza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6960b', 'spa', 'reunir, juntar; congregarse en un lugar, usado de aguas y naciones (Nifal)', 'Esta raíz verbal significa reunir o juntar. Génesis 1:9 manda que las aguas se reúnan en un solo lugar, permitiendo que aparezca la tierra seca—un acto fundacional de la creación ordenando el caos. Isaías 60:9 habla de naves que ''esperan'' o posiblemente ''se congregan'' (cuestión textual) al Señor. Jeremías 3:17 profetiza que las naciones se congregarán en Jerusalén. La forma Nifal indica acción pasiva o reflexiva: ser reunido o reunirse. El traslape semántico con ''esperar'' (raíz homónima) crea cierta ambigüedad interpretativa en algunos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6961', 'spa', 'línea, cordel; cordel de medir o hilo, particularmente en construcción (forma Ketiv)', 'Este sustantivo (una variante Ketiv relacionada con H6957) significa una línea o cordel usado para medir. El Qere (lectura preferida) generalmente lo vocaliza como ''qav'' (קַו), mientras que el Ketiv (texto escrito) preserva esta forma variante. Primero Reyes 7:23 lo usa para medir la circunferencia del mar de bronce. Jeremías 31:39 habla de un cordel de medir que saldrá sobre Jerusalén. Zacarías 1:16 menciona dos veces una línea extendida sobre Jerusalén en restauración—el cordel del constructor marcando futura expansión. El término pertenece al vocabulario de construcción y agrimensura, representando esperanza y reconstrucción en textos proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6962', 'spa', 'Sentir asco, repugnancia profunda o aborrecimiento de sí mismo; en Hitpael, contender o luchar contra', 'Este verbo captura una repulsión visceral en su núcleo. En el Salmo 95:10, Dios declara ''sentí fastidio de aquella generación'', un disgusto de cuarenta años hacia un pueblo rebelde. Ezequiel emplea el Nifal de forma reflexiva: Israel ''se aborrecerá a sí mismo'' ante sus propios ojos al recordar sus abominaciones (Ezek 6:9; 20:43; 36:31). El Hitpael intensifica la emoción hasta convertirla en confrontación activa: el salmista en 119:158 siente repugnancia ante los desleales, y en 139:21 ''contiende con'' quienes se levantan contra Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6963a', 'spa', 'Voz, sonido; habla humana, palabra divina, trueno, ruido o noticia — la expresión audible de voluntad o acontecimiento', 'Uno de los sustantivos con mayor carga teológica de la Biblia hebrea, קוֹל abarca toda la gama de fenómenos audibles, desde un susurro hasta un trueno. Denota la voz humana en el habla, el llanto y el canto, pero alcanza su mayor peso en la frase קוֹל יהוה, la voz del SEÑOR que manda, juzga y revela. El plural קוֹלוֹת designa característicamente los truenos, vinculando la teofanía de tormenta con el habla divina. En la expresión de obediencia שָׁמַע בְּקוֹל, la voz misma se convierte en metonimia de autoridad, haciendo del oír algo inseparable del obedecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6965b', 'spa', 'Levantarse, alzarse, ponerse en pie; permanecer firme, perdurar; causativo: suscitar, establecer, erigir, cumplir', 'Verbo de movimiento vertical y estabilidad. El sentido básico del Qal es el alzamiento físico — levantarse de estar sentado o acostado, ponerse en acción — dominando la narrativa con וַיָּקָם (''y se levantó''). Pero קוּם también significa mantenerse firme, perdurar, permanecer vigente: el consejo que ''permanece'', los reinos que ''perduran''. El Hifil causativo multiplica los significados: suscitar un profeta o juez en el escenario de la historia, establecer un pacto o trono, erigir una estructura como el tabernáculo, o cumplir una promesa. El Piel y el Hitpael añaden confirmación intensiva y oposición hostil. Una sola raíz abarca postura física, estabilidad existencial y fidelidad pactual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6966', 'spa', 'Levantarse, erigir, establecer; qum arameo en Daniel y Esdras para alzarse, erigir y nombrar', 'Levantarse, erigir, establecer; qum arameo en Daniel y Esdras para alzarse, erigir y nombrar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6967', 'spa', 'Altura, estatura; la medida vertical de una estructura o la constitución física de una persona', 'Altura, estatura; la medida vertical de una estructura o la constitución física de una persona');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6969', 'spa', 'Entonar una endecha, lamentar, plañir; denominativo Pi''el de qinah (lamento), usado en ritos funerarios formales.', 'Verbo denominativo en Pi''el derivado de qinah (''endecha'' o ''lamento''), qonen designa el canto formal de una elegía fúnebre o cántico de duelo. David emplea este verbo al componer sus lamentaciones públicas sobre Saúl y Jonatán (2 S 1:17) y sobre Abner (2 S 3:33). Ezequiel lo usa para endechas proféticas sobre Tiro (27:32) y Egipto (32:16), mientras Jeremías 9:17 menciona a plañideras profesionales (meqonenot) convocadas para llorar. El verbo subraya el carácter ritualizado y vocal de este duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6973', 'spa', 'Sentir repugnancia o aborrecimiento; sentir un pavor angustioso o terror; en causativo, aterrorizar.', 'Un verbo visceral que describe reacciones que revuelven el estómago, ya sea por asco o por pavor. Rebeca declara ''estoy hastiada de mi vida'' por causa de las mujeres hititas (Gn 27:46), y Dios mismo ''se asqueó'' de las naciones de Canaán (Lv 20:23). Pero la misma raíz también describe el terror helado que paraliza a una nación ante un enemigo amenazante: Egipto sintió pavor ante los israelitas que se multiplicaban (Ex 1:12), y Moab se angustió ante Israel (Nm 22:3). El español distingue bellamente estos matices: ''hastiada'' para la repugnancia y ''se angustiaron'' para el pavor. Una forma causativa Hifil poco frecuente aparece en Isaías 7:6, donde los conspiradores traman ''aterrorizar'' a Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6974', 'spa', 'Despertar del sueño (literal o el sueño de la muerte); levantarse con urgencia para actuar.', 'Despertar del sueño (literal o el sueño de la muerte); levantarse con urgencia para actuar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6975', 'spa', 'Espino, zarza — planta espinosa; literalmente matorral del desierto, figuradamente juicio e inutilidad', 'El sustantivo קוֹץ (qots) designa espinos o zarzas, una de las imágenes botánicas más versátiles de las Escrituras. Su aparición fundacional está en la maldición primordial: «espinos y cardos te producirá» (Gn 3:18), estableciendo los espinos como signo de la rebelión de la tierra. En lo práctico, Éxodo 22:6 legisla sobre el fuego que se propaga entre espinos hasta el grano del vecino, y Gedeón castiga a los hombres de Sucot con «espinos del desierto» (Jue 8:7, 16). En sentido figurado, los espinos señalan desolación (Is 32:13), trabajo inútil (Jer 12:13), maldad (2 S 23:6) y enemigos que crepitan como espinos ardientes (Sal 118:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6976', 'spa', 'Cos / Hacos; nombre propio de un jefe de clan judahíta y de una familia sacerdotal en el Israel postexílico.', 'Nombre propio masculino, Qots (Cos), que aparece frecuentemente con el artículo definido como Haqqots (Hacos). Designa a dos figuras distintas: un nombre en la genealogía de Judá (1 Chr 4:8) y, de forma más destacada, al jefe de la séptima división sacerdotal asignada por sorteo en la organización del servicio del templo por David (1 Chr 24:10). La familia sacerdotal de Hacos reaparece en el período postexílico: algunos descendientes no pudieron demostrar su genealogía y fueron excluidos del sacerdocio (Ezra 2:61; Neh 7:63), mientras que otros contribuyeron a la reconstrucción de los muros de Jerusalén (Neh 3:4, 21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6978', 'spa', 'cordel, línea de medir; posiblemente «poderoso» (significado incierto y debatido en Isaías 18)', 'Palabra difícil que aparece solo en Isaías 18:2, 7 en la frase que describe «una nación de cordel cordel» o «una nación poderosa, poderosa». Algunos intérpretes la entienden como una reduplicación que significa «poderoso» (relacionada con el árabe «fuerza»). Otros la leen como «de cordel de medir, cordel de medir», es decir, una nación que mide y conquista tierras. La reduplicación intensifica el significado, pero el sentido exacto sigue en debate. Las traducciones modernas varían considerablemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6981', 'spa', 'Coré; nombre personal de levitas, incluyendo porteros y uno que distribuyó ofrendas en tiempo de Ezequías', 'Coré es el nombre de al menos dos levitas en Crónicas. Primera de Crónicas 9:19 y 26:1 se refieren a Coré hijo de Ebiasaf, un portero coreíta responsable del umbral de la tienda—una posición de confianza custodiando el santuario. Segunda de Crónicas 31:14 menciona a Coré hijo de Imna, un levita ubicado en la Puerta Oriental que distribuía las ofrendas voluntarias durante las reformas de Ezequías. El nombre puede derivar de una raíz que significa ''llamar'' o ''perdiz''. Estos levitas sirvieron en la administración del templo, vinculando el nombre al servicio fiel en la casa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6982', 'spa', 'Viga, cabrio; madera estructural usada en la construccion de techos o cielos rasos', 'Sustantivo que designa una pieza de madera estructural, en particular una viga de techo o cabrio. En Genesis 19:8 Lot invoca la proteccion de ''mi techo'' (literalmente ''mi viga''), reflejando la antigua ley de hospitalidad del Cercano Oriente bajo el propio techo. En 2 Reyes 6:2, 5 los hijos de los profetas cortan vigas para una nueva morada, y la cabeza de un hacha cae celebremente al Jordan. 2 Cronicas 3:7 menciona las vigas del templo de Salomon recubiertas de oro, y Cantar de los Cantares 1:17 celebra vigas de cedro en un entorno pastoral amoroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6986', 'spa', 'destrucción, pestilencia; calamidad mortal, a menudo personificada como agente de juicio', 'Este sustantivo denota destrucción o pestilencia mortal—una fuerza de juicio catastrófico. Deuteronomio 32:24 lo empareja con ''calor abrasador'' (reshef) entre los desastres que Dios envía. Salmo 91:6 menciona ''la destrucción que devasta al mediodía'', paralelo a ''la pestilencia que anda en oscuridad''. Isaías 28:2 habla de una ''tempestad de destrucción''. Oseas 13:14 lo personifica: ''¿Dónde están tus plagas, oh muerte? ¿Dónde está tu destrucción, oh Seol?''—fuerzas divinas convocadas contra Israel. El término evoca ruina violenta, ya sea por enfermedad, desastre o ira divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6989', 'spa', 'Quetura (nombre propio, esposa de Abraham después de la muerte de Sara)', 'Nombre de la esposa de Abraham tras la muerte de Sara, madre de seis hijos que se convirtieron en ancestros de tribus árabes. Génesis 25:1, 4 registra su matrimonio con Abraham y su descendencia. 1 Crónicas 1:32-33 presenta la misma genealogía, aunque allí se la llama concubina en lugar de esposa. El nombre podría derivar de una raíz que significa «incienso» (קְטֹרֶת), sugiriendo quizás «la perfumada» o «mujer del incienso», aunque esto es incierto. A través de los hijos de Quetura, Abraham llegó a ser padre de numerosos pueblos de Arabia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6991', 'spa', 'matar, dar muerte; término poético/tardío para quitar la vida, usado de violencia humana y juicio divino', 'Este verbo significa matar o dar muerte, apareciendo en textos bíblicos poéticos y tardíos. Job 13:15 expresa fe desafiante: ''Aunque él me mate, en él confiaré''. Job 24:14 describe al asesino que se levanta para matar al pobre. Salmo 139:19 suplica a Dios: ''¡Oh, si mataras al impío!'' El término es más elevado o literario que el común ''harag'', usado en poesía y literatura sapiencial. La raíz es compartida en las lenguas semíticas (árabe qatala, arameo qetal), indicando vocabulario común antiguo para matar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6992', 'spa', 'Matar, dar muerte (activo); ser muerto, ser ejecutado (pasivo) — verbo arameo exclusivo de Daniel.', 'El verbo arameo קְטַל (''matar'') aparece únicamente en el libro de Daniel, donde lleva todo el peso de la violencia imperial y el juicio divino. En sus formas activas, Nabucodonosor ejerce poder absoluto para matar a quien desee (Dn 5:19), sus soldados matan a los hombres que arrojaron a Sadrac, Mesac y Abednego al horno (Dn 3:22), y se decreta la ejecución de los sabios (Dn 2:14). En sus formas pasivas, Belsasar es muerto la misma noche en que aparece la escritura en la pared (Dn 5:30), y la cuarta bestia es ejecutada ante el Anciano de Días (Dn 7:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6994', 'spa', 'ser pequeño, insignificante, indigno; hacer pequeño, disminuir', 'Verbo que en Qal significa ser pequeño, insignificante o indigno, y en Hifil, hacer pequeño o disminuir. En Génesis 32:10, Jacob confiesa «soy indigno (קָטֹנְתִּי) de toda la misericordia» que Dios le ha mostrado, expresando profunda humildad. En 2 Samuel 7:19 y su paralelo en 1 Crónicas 17:17, David se maravilla de que las promesas divinas fueran «poca cosa a tus ojos» (וַתִּקְטַן זֹאת בְּעֵינֶיךָ), pues Dios fue más allá de lo esperado. Amós 8:5 condena a los comerciantes que «achican la efa» (לְהַקְטִין הָאֵיפָה), engañando con medidas reducidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6996a', 'spa', 'Pequeño, joven o menor; de tamaño diminuto, edad más joven o rango más bajo dentro de un grupo', 'Pequeño, joven o menor; de tamaño diminuto, edad más joven o rango más bajo dentro de un grupo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6996b', 'spa', 'Pequeño, poco o insignificante; menor o más joven en edad o rango; el extremo inferior en la fórmula «desde el menor hasta el mayor».', 'Pequeño, poco o insignificante; menor o más joven en edad o rango; el extremo inferior en la fórmula «desde el menor hasta el mayor».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6998', 'spa', 'Arrancar, cortar (ramas, espigas, plantas); ser arrancado', 'Verbo concreto del ambito agricola que describe la accion de arrancar o cortar vegetacion con la mano. En Deuteronomio 23:25 autoriza arrancar espigas al pasar por el campo del projimo, mientras que en Ezequiel 17:4, 22 aparece en la notable alegoria del aguila, donde Dios arranca un tierno renuevo de la cima del cedro del Libano. Job 30:4 emplea el participio para los indigentes que arrancan malvas como alimento. Las cinco ocurrencias involucran siempre material vegetal, convergiendo en la idea de extraccion manual y forzada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6999a', 'spa', 'Quemar sacrificios sobre el altar o incienso en el culto o la idolatría; abarca el Piel (incienso) y el Hifil (ofrendas)', 'Verbo distintivamente cúltico cuyas dos conjugaciones principales dividen el mundo ritual: en el Piel describe la quema de incienso (קְטֹרֶת), mientras que en el Hifil se refiere al acto de hacer subir en humo las porciones grasas y los sacrificios sobre el altar. El árabe preserva un desdoblamiento paralelo entre بَخَّرَ (sahumar con incienso) y أَوْقَدَ (encender fuego), reflejando con notable fidelidad la distinción hebrea de conjugaciones. Un caso poético aislado en Cantares 3:6 emplea un participio para evocar la fragancia del perfume más que la quema sacrificial, apuntando al significado aromático que subyace a ambos usos cultuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7001', 'spa', 'articulaciones, nudos; posiblemente articulaciones anatómicas o problemas difíciles/hechizos que requieren solución (arameo)', 'Este sustantivo arameo aparece en Daniel 5 con significado debatido. Daniel 5:6 describe la reacción física de Belsasar ante la escritura en la pared: ''las articulaciones de sus caderas se aflojaron''—posiblemente sus articulaciones de cadera o rodillas cediendo por terror. Daniel 5:12, 16 hablan de la habilidad de Daniel para resolver ''nudos'' o ''dificultades''—ya sea problemas complicados que requieren solución o posiblemente hechizos mágicos que necesitan romperse. El cognado siríaco apoya tanto ''articulaciones'' (anatómico) como ''nudos/dificultades'' (intelectual/mágico). El término opera literalmente (partes del cuerpo) y figurativamente (problemas) dentro del mismo capítulo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7004', 'spa', 'Incienso — especias aromáticas compuestas y quemadas como ofrenda sagrada ante YHWH en el tabernáculo y el templo.', 'Incienso — especias aromáticas compuestas y quemadas como ofrenda sagrada ante YHWH en el tabernáculo y el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7008', 'spa', 'humo espeso, humo denso (que se eleva de un incendio o conflagración)', 'Sustantivo que designa humo espeso y denso que se eleva de un fuego o destrucción. Génesis 19:28 describe dos veces el humo que subía de las ciudades de la llanura «como el humo de un horno» (כְּקִיטֹר הַכִּבְשָׁן). El Salmo 119:83 lo emplea metafóricamente: «soy como un odre en el humo» (כְּנֹאד בְּקִיטוֹר), ennegrecido y marchito por la exposición. El Salmo 148:8 presenta dificultad textual, pues el hebreo dice «humo», pero versiones antiguas leen «escarcha» (קֶרַח). La palabra evoca el humo denso y sofocante de una conflagración intensa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7014b', 'spa', 'Caín — hijo primogénito de Adán y Eva, el primer homicida en la narrativa bíblica. El nombre propio del hijo mayor de Adán y Eva, cuya ofrenda Dios re', 'Caín — hijo primogénito de Adán y Eva, el primer homicida en la narrativa bíblica. El nombre propio del hijo mayor de Adán y Eva, cuya ofrenda Dios rechazó mientras aceptaba la de Abel, precipitando el primer asesinato (Gn 4:1-8). Génesis explica el nombre mediante un juego de palabras con קָנָה (''adquirir''), cuando Eva declara ''He adquirido un varón con la ayuda del SEÑOR'' (Gn 4:1). Después de matar a Abel, Caín recibe una marca protectora y sale a habitar en la tierra de Nod, al oriente de Edén, donde funda una ciudad (Gn 4:15-17). Las dieciséis ocurrencias se encuentran dentro de la narrativa yahvista de Génesis 4.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7015', 'spa', 'Lamentación, endecha, canto fúnebre — un poema luctuoso compuesto para llorar a los muertos o una catástrofe. Este sustantivo femenino denota un lamen', 'Lamentación, endecha, canto fúnebre — un poema luctuoso compuesto para llorar a los muertos o una catástrofe. Este sustantivo femenino denota un lamento poético formal, típicamente compuesto en el metro distintivo de la קִינָה (patrón acentual 3+2) que se convirtió en sello de la poesía elegíaca bíblica. El lamento de David por Saúl y Jonatán (2 S 1:17) se introduce con esta palabra. Ezequiel recibe el mandato especial de ''elevar una קִינָה'' sobre Tiro (27:2), Egipto (32:2) y los príncipes de Israel (19:1). Jeremías llama a las mujeres a aprender y enseñar la endecha (Jer 9:19). El término aparece junto a palabras para duelo (אֵבֶל) y lamento (נְהִי), situándolo firmemente dentro de la rica tradición israelita de duelo ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7017', 'spa', 'Cenita (קֵינִי); adjetivo gentilicio que designa al clan seminómada aliado de Israel, asociado con Caín y la metalurgia. Los cenitas aparecen por prim', 'Cenita (קֵינִי); adjetivo gentilicio que designa al clan seminómada aliado de Israel, asociado con Caín y la metalurgia. Los cenitas aparecen por primera vez entre los pueblos de Canaán (Gn 15:19), y su alianza con Israel es profunda: el suegro de Moisés era cenita (Jue 1:16), Jael, esposa de Heber el cenita, mató a Sísara (Jue 4:11, 17; 5:24), y Saúl advirtió a los cenitas antes de atacar a Amalec porque habían mostrado bondad a Israel (1 S 15:6). El oráculo de Balaam sobre sus moradas en los peñascos (Nm 24:21) juega con el nombre mismo del clan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7018', 'spa', 'Quenán (Cainán); patriarca setita, hijo de Enós y padre de Mahalalel, en la genealogía antediluviana.', 'Nombre propio masculino, Quenán (también Cainán), un patriarca setita en la genealogía antediluviana. Hijo de Enós y padre de Mahalalel, vivió 910 años según Génesis 5:9-14. El nombre aparece seis veces: cinco en Génesis 5, cubriendo su nacimiento, la generación de Mahalalel y su muerte, más una vez en la genealogía comprimida de 1 Crónicas 1:2. Las transliteraciones al español ''Quenán'' y ''Cainán'' reflejan las convenciones estándar, mientras que las dos variantes menores del grupo (Qeynan y Qenan) representan diferencias de vocalización sin distinción semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7019', 'spa', 'Verano como estación de calor y cosecha; también la fruta madura de verano misma, especialmente higos y productos de cosecha tardía. En el calendario ', 'Verano como estación de calor y cosecha; también la fruta madura de verano misma, especialmente higos y productos de cosecha tardía. En el calendario agrícola hebreo, קַיִץ marca la estación calurosa y seca que se extiende desde la siega de cereales hasta la recolección de higos y uvas. Más allá de nombrar la estación, la palabra también denota la fruta de verano recogida durante ella — particularmente higos, como se ve cuando David recibe tortas de fruta de verano (2 S 16:1-2). El famoso juego de palabras en Amós 8:1-2 entre קַיִץ (''fruta de verano'') y קֵץ (''fin'') transforma una canasta de higos maduros en una señal profética de que el fin de Israel ha llegado, vinculando la madurez agrícola con el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7020', 'spa', 'exterior, extremo (el que está al final de una serie o borde)', 'Adjetivo que significa exterior o extremo, referido a lo que está al final de una serie. Aparece exclusivamente en Éxodo 26 y 36 al describir las cortinas del tabernáculo. Especifica cuál cortina es «la extrema» (הַקִּיצֹנָה) en cada juego, es decir, la que se encuentra en el borde de la serie y debe unirse al juego contiguo mediante lazadas y broches. Este término técnico arquitectónico distingue la cortina exterior de las interiores, asegurando la correcta construcción del tabernáculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7021', 'spa', 'Ricino, calabacera; la planta de rapido crecimiento que Dios preparo para dar sombra a Jonas', 'Sustantivo que aparece exclusivamente en Jonas 4:6-10, donde designa la planta de rapido crecimiento que Dios preparo para dar sombra al renuente profeta y que luego destruyo con un gusano. Su identidad botanica exacta ha sido largamente debatida. El termino ''ricino'' refleja la identificacion rabinica tradicional y la de la Septuaginta con Ricinus communis, conocido por su veloz crecimiento en el clima levantino. La narrativa emplea esta planta para ensenar a Jonas sobre la compasion divina hacia Ninive.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7023', 'spa', 'Pared; muro estructural de un edificio, casa o templo; ocasionalmente un muro de fortificación urbana.', 'Pared; muro estructural de un edificio, casa o templo; ocasionalmente un muro de fortificación urbana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7024b', 'spa', 'Kir (topónimo; lugar en Mesopotamia o Siria; también parte de nombres moabitas como Kir-moab)', 'Nombre de lugar que aparece en dos contextos: (1) una ubicación, posiblemente en Mesopotamia o Siria, de donde procedían los arameos y adonde Asiria los deportó (Amós 1:5; 9:7; 2 Reyes 16:9); (2) componente de nombres de ciudades moabitas como Kir-moab y Kir-hareset. En 2 Reyes 16:9, Tiglat-pileser deporta a los habitantes de Damasco «a Kir» (קִירָה). Amós 9:7 recuerda que Dios trajo «a los arameos desde Kir». Isaías 22:6 menciona a Kir junto a Elam en contexto militar. Su ubicación exacta sigue siendo incierta, aunque se proponen regiones en Mesopotamia o el alto Éufrates.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7025', 'spa', 'Kir-Hareset, ciudad fortificada moabita (actual Kerak, Jordania); también llamada Kir-Heres.', 'Kir-Hareset (también escrita Kir-Heres) fue una importante ciudad fortificada de Moab, ampliamente identificada con la moderna al-Karak en Jordania. El nombre compuesto combina qir (''muro'') con chareseth o cheres (''tiesto'' o ''alfarería''), posiblemente aludiendo a sus murallas o a su industria cerámica. Aparece en el relato de la campaña de Joram contra Moab (2 R 3:25) y de manera prominente en los oráculos proféticos contra Moab en Isaías 16:7, 11 y Jeremías 48:31, 36, donde su caída provoca lamento y duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7027', 'spa', 'Quis (קִישׁ), nombre propio hebreo portado por varios hombres, siendo el más notable el padre del rey Saúl. El nombre significa posiblemente ''arco'' o ', 'Quis (קִישׁ), nombre propio hebreo portado por varios hombres, siendo el más notable el padre del rey Saúl. El nombre significa posiblemente ''arco'' o ''trampa''. El portador más prominente es el benjamita padre de Saúl, primer rey de Israel (1 Sam 9:1, 3; 10:11, 21; 14:51), cuya genealogía se traza en 1 Crónicas 8:30, 33 y 9:36, 39. Otros individuos llamados Quis incluyen un levita en la era de David (1 Cr 23:21–22; 24:29) y un antepasado de Mardoqueo (Est 2:5). Las traducciones en distintos idiomas transliteran uniformemente el nombre, reflejando su identidad estable como nombre personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7028', 'spa', 'Cisón (Qishón); río o wadi estacional en el norte de Israel, escenario de la derrota de Sísara y la ejecución de los profetas de Baal por Elías.', 'Nombre propio Qishón (Cisón), un río estacional o wadi en el valle de Jezreel, al norte de Israel. Es célebre como el lugar donde Dios derrotó al ejército de Sísara: el torrente del Cisón arrastró los carros cananeos (Jue 4:7, 13; 5:21). El cántico de Débora celebra con feroz intensidad poética al «río antiguo» (nahal qedumim), el Cisón. El río reaparece en 1 Reyes 18:40, cuando Elías lleva a los profetas de Baal al arroyo Cisón y los ejecuta tras la confrontación en el monte Carmelo. En el Salmo 83:9, el salmista ruega que Dios trate a los enemigos actuales de Israel como trató a Sísara junto al Cisón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7030', 'spa', 'Lira, cítara; préstamo arameo del griego kitharis, incluido entre los instrumentos de la corte de Nabucodonosor.', 'Sustantivo arameo tomado del griego kitharis (κίθαρις), qithros designa un instrumento de cuerdas — una lira o cítara — mencionado exclusivamente en Daniel 3:5, 7, 10 y 15. Aparece en la lista de instrumentos cuyo sonido señalaba el momento de postrarse ante la imagen de oro de Nabucodonosor. La variación ketiv-qere (qithros/qathros) refleja la ortografía fluctuante de este préstamo extranjero en arameo. Su identificación uniforme en diversas lenguas — español ''cítara'', francés ''lyre'', inglés ''lyre'' — confirma que se trata de un instrumento de cuerdas pulsadas de la familia del arpa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7031', 'spa', 'Veloz, ligero, ágil de pies (קַל); adjetivo que describe movimiento rápido de personas, animales, mensajeros o nubes. Describe a guerreros ligeros de ', 'Veloz, ligero, ágil de pies (קַל); adjetivo que describe movimiento rápido de personas, animales, mensajeros o nubes. Describe a guerreros ligeros de pies (Am 2:14–15; 2 S 2:18, sobre Asael), mensajeros veloces enviados en misiones urgentes (Is 18:2), perseguidores más rápidos que águilas (Lm 4:19) e incluso al SEÑOR cabalgando sobre una nube ligera (Is 19:1). Eclesiastés 9:11 lo usa proverbialmente —''la carrera no es de los veloces''— subvirtiendo la misma cualidad que la palabra celebra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7032', 'spa', 'Sonido, voz (arameo); usado en Daniel para proclamaciones audibles y el sonido de instrumentos musicales.', 'Sustantivo arameo para ''sonido'' o ''voz'', cognado del hebreo qol. En Daniel cumple una doble función: denota el sonido de los instrumentos musicales que señalan el momento de postrarse ante la imagen de oro de Nabucodonosor (Dn 3:5, 7, 10, 15), y se refiere a una voz hablada — la voz celestial que anuncia el juicio sobre Nabucodonosor (Dn 4:31) y la propia voz del rey llamando a Daniel en el foso de los leones (Dn 6:20). El español distingue bien entre ''sonido de'' (instrumentos) y ''voz'' (palabra hablada), reflejando con precisión su doble aplicación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7033', 'spa', 'tostar, asar (con fuego); ser quemado o abrasado', 'Verbo que significa tostar, asar o quemar, aplicado típicamente a granos o personas. Levítico 2:14 prescribe ofrecer «grano de espigas frescas tostado al fuego» (אָבִיב קָלוּי בָּאֵשׁ). Josué 5:11 menciona el consumo de «grano tostado» (קָלוּי) tras cruzar el Jordán. Jeremías 29:22 describe gráficamente cómo Nabucodonosor «los quemó en el fuego» (קָלָם בָּאֵשׁ), refiriéndose a falsos profetas. El Salmo 38:7 lo usa metafóricamente: «mis lomos están llenos de ardor» (נִקְלֶה), aunque algunos interpretan «desprecio» si proviene de otra raíz. El sentido fundamental involucra calor intenso y fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7034', 'spa', 'Ser menospreciado, deshonrado, tenido en poco (Nifal); deshonrar, tratar con desprecio (Hifil).', 'Forma paralela del más frecuente qalal («ser liviano»), este verbo se centra específicamente en la deshonra social y la inversión de la estima. En sus usos en Nifal (pasivo), describe a personas o naciones reducidas a la insignificancia: David se llama a sí mismo «pobre y menospreciado» ante Saúl (1 Sam 18:23), Isaías profetiza que la gloria de Moab «será deshonrada» (Isa 16:14), y Proverbios 12:9 contrasta desfavorablemente al arrogante con el humilde. La única ocurrencia en Hifil lleva el peso de una maldición del pacto: «Maldito el que deshonre a su padre o a su madre» (Deut 27:16), invirtiendo directamente el quinto mandamiento de «honrar».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7036', 'spa', 'Vergüenza, deshonra, ignominia; la humillación pública resultante del pecado, la necedad o el juicio divino. Sustantivo de gran peso tanto en el vocab', 'Vergüenza, deshonra, ignominia; la humillación pública resultante del pecado, la necedad o el juicio divino. Sustantivo de gran peso tanto en el vocabulario profético como sapiencial. קָלוֹן designa la ruina social que sigue al fracaso moral o a la sentencia divina. Proverbios lo contrasta repetidamente con כָּבוֹד (''honor''): los sabios heredan honra, pero la vergüenza es la porción de los necios (Prov 3:35). Los profetas lo emplean para exponer la degradación nacional: Oseas 4:7 advierte que Israel ha cambiado su gloria por deshonra, y Nahúm 3:5 lo usa para la desnudez expuesta como humillación pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7039', 'spa', 'Grano tostado o cereal tostado, alimento común del antiguo Cercano Oriente preparado con espigas frescas de trigo o cebada.', 'Alimento básico del antiguo Israel, preparado tostando al fuego espigas recién cosechadas de trigo o cebada. El grano tostado era económico, portátil y nutritivo, ideal para viajeros, soldados y trabajadores del campo. Cuando Booz invita a Rut a mojar su porción en vinagre durante la comida (Rut 2:14), o cuando Abigail reúne apresuradamente provisiones que incluyen grano tostado para los hombres de David (1 Sam 25:18), vislumbramos la importancia cotidiana de este humilde alimento. El calendario levítico prohíbe comer grano tostado antes de la ofrenda de las primicias (Lev 23:14), subrayando su significado agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7042', 'spa', 'Quelita; nombre personal de un levita involucrado en las reformas de Esdras, también llamado Quelaías', 'Quelita fue un levita activo durante el tiempo de Esdras. Esdras 10:23 lo enumera (también llamado Quelaías) entre los levitas que se habían casado con mujeres extranjeras y acordaron divorciarse de ellas. Nehemías 8:7 lo nombra entre los levitas que ayudaron al pueblo a entender la Ley cuando Esdras la leyó públicamente. Nehemías 10:10 (hebreo 10:11) lo incluye entre quienes sellaron la renovación del pacto. El nombre doble (Quelita/Quelaías) puede indicar un nombre de nacimiento y otro nombre tomado después. Él ejemplifica levitas involucrados en la enseñanza y renovación del pacto durante las reformas post-exílicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7043', 'spa', 'Ser ligero, veloz, trivial; maldecir; aligerar; despreciar; sacudir.', 'Ser ligero, veloz, trivial; maldecir; aligerar; despreciar; sacudir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7045', 'spa', 'maldición, imprecación — pronunciamiento solemne que invoca daño, frecuentemente opuesto a bendición en contextos de pacto', 'maldición, imprecación — pronunciamiento solemne que invoca daño, frecuentemente opuesto a bendición en contextos de pacto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7046', 'spa', 'burlarse, mofarse, escarnecer con desprecio', 'Este verbo poco frecuente aparece solo en la conjugacion Hitpael, expresando burla reflexiva o intensiva y escarnio. El termino capta la mofa despectiva, ya sean jovenes burlándose del profeta Eliseo, gobernantes mofándose de las fortificaciones, o Jerusalen representada como quien desprecia el pago como una ramera que desdeña su salario. La evidencia multilingue apunta consistentemente a la burla y el desprecio en diversos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7047', 'spa', 'escarnio, burla; ser objeto de desprecio y ridículo, a menudo emparejado con oprobio', 'Este sustantivo significa escarnio o burla—ser objeto de desprecio. El Salmo 44:13 lamenta que Dios ha hecho de Israel ''un refrán y escarnio entre los pueblos''. El Salmo 79:4 declara de manera similar: ''Somos oprobio para nuestros vecinos, escarnio y burla para los que nos rodean''. Jeremías 20:8 describe la experiencia del profeta: su mensaje lo convierte en objeto de ''oprobio y escarnio todo el día''. El término típicamente se empareja con ''oprobio'' (cherpah) y ''burla'' (laag), formando un conjunto que expresa humillación social y desprecio. El sufrimiento de Israel o del profeta incluye ser objeto de risa y mofa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7049a', 'spa', 'lanzar con honda, arrojar con fuerza', 'Este verbo designa la accion de lanzar piedras con honda o arrojar objetos con fuerza, enraizado en la guerra antigua y la vida pastoril. Famoso por la victoria de David sobre Goliat, el termino tambien aparece en contextos legales (apedreamiento) e imagenes profeticas (Dios arrojando a los habitantes). La raiz puede conectarse con la idea de soltar o oscilar, en consonancia con el movimiento de una honda al liberar su proyectil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7049b', 'spa', 'tallar, grabar diseños decorativos en madera o piedra', 'Este verbo describe el oficio especializado de tallar diseños decorativos en superficies, específicamente las paredes interiores y puertas del templo de Salomón. El uso consistente en español (talló), francés (sculpté) y alemán (carved) refleja la naturaleza artística de esta obra sagrada. Las tres apariciones se encuentran en 1 Reyes 6, describiendo los querubines ornamentados y patrones florales tallados en la madera de cedro del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7050a', 'spa', 'Honda, arma de mano utilizada para lanzar piedras contra enemigos o presas.', 'La honda fue una de las armas de alcance más eficaces del antiguo Cercano Oriente, compuesta por una bolsa sujeta a dos cuerdas capaz de lanzar una piedra con fuerza y precisión letales. Su aparición más célebre es la victoria de David sobre Goliat con una sola piedra de su honda de pastor (1 Sam 17:40, 50). La metáfora de 1 Samuel 25:29, donde Abigail contrasta estar «atado en el haz de los que viven» con los enemigos lanzados «como de en medio de la palma de una honda», evoca poderosamente la trayectoria violenta del arma. En tiempos del Cronista, las hondas eran equipo militar estándar asignado a las tropas de guarnición (2 Cr 26:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7050b', 'spa', 'Cortinas o colgaduras usadas en el atrio del Tabernáculo; en una variante textual se lee como ''hojas'' (de una puerta). Sustantivo de la fuente sacerdo', 'Cortinas o colgaduras usadas en el atrio del Tabernáculo; en una variante textual se lee como ''hojas'' (de una puerta). Sustantivo de la fuente sacerdotal que aparece casi exclusivamente en Éxodo, referido a las cortinas tejidas que cercaban el atrio del Tabernáculo. Estos paneles de tela, suspendidos entre columnas, formaban el límite visible del recinto sagrado en sus cuatro lados (Éx 27:9-15; 38:9-18). El término es un vocablo básico de la construcción del Tabernáculo en Éxodo y Números. Una ocurrencia en 1 Reyes 6:34 es probablemente un error textual por צְלָעִים (''hojas'' de una puerta plegable), como señala BDB, produciendo un sentido secundario único.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7054', 'spa', 'Mies en pie; cultivos de cereal sin cosechar, erguidos en el campo; a veces extendido a crecimiento, alzarse o el tallo mismo', 'Designa los cultivos de cereal —trigo y cebada— que permanecen erguidos en el campo antes de la cosecha. La palabra aparece de manera prominente en la legislación agrícola: Éxodo 22:6 trata sobre el fuego que se extiende a la mies en pie, Deuteronomio 16:9 marca el inicio de la siega cuando la hoz toca la קָמָה, y Deuteronomio 23:25 permite arrancar espigas a mano del campo del prójimo. Los zorros de Sansón prendieron fuego a la mies en pie de los filisteos en Jueces 15:5. Oseas 8:7 emplea la imagen de manera metafórica —«el tallo no tiene grano»— para retratar la idolatría estéril de Israel, que no produce nada de provecho.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7055', 'spa', 'Kemuel, nombre de tres hombres diferentes en el Antiguo Testamento', 'Kemuel aparece como el nombre de tres individuos distintos en las Escrituras: un hijo de Nacor (hermano de Abraham), un líder efraimita que asistió en la distribución de la tierra, y un levita. La Septuaginta lo traduce consistentemente como Καμουηλ. La raíz hebrea del nombre sugiere significados relacionados con ''Dios ha levantado'' o ''asamblea de Dios'', aunque como nombre propio funciona principalmente como identificador en diferentes contextos tribales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7058', 'spa', 'Harina o harina gruesa (קֶמַח); grano molido usado para hornear pan, preparar ofrendas y el sustento diario. Se distingue de la harina fina (סֹלֶת) en', 'Harina o harina gruesa (קֶמַח); grano molido usado para hornear pan, preparar ofrendas y el sustento diario. Se distingue de la harina fina (סֹלֶת) en las provisiones de Salomón (1 R 4:22); es el producto básico del hogar guardado en una tinaja, como la menguante provisión de la viuda de Sarepta que milagrosamente perduró (1 R 17:12, 14, 16). Aparece en contextos de ofrendas (Nm 5:15, harina de cebada para la ofrenda por celos) y en la cocina cotidiana (Jue 6:19; 1 S 28:24). Oseas la usa metafóricamente: la espiga de Israel ''no produce harina'' (Os 8:7), imagen vívida de una política nacional infructuosa. Isaías 47:2 representa a Babilonia moliendo harina en el molino como señal de humillación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7061', 'spa', 'tomar un puñado, agarrar con la mano (usado en ritual sacerdotal)', 'Este verbo describe la acción ritual precisa de un sacerdote tomando un puñado de flor de harina como porción memorial durante las ofrendas de grano. El gesto aparece exclusivamente en la legislación sacerdotal, siempre involucrando al sacerdote agarrando ''su puñado completo'' de la ofrenda. La evidencia multilingüe (español ''tomará puñado'', francés ''prendre un handful'', alemán ''nehmen ein Handvoll'') enfatiza la naturaleza medida y deliberada de este gesto litúrgico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7062', 'spa', 'mano cerrada, puno, punado', 'Este sustantivo describe la mano cerrada como medida de cantidad: un punado. En la legislacion sacerdotal, especifica la porcion de la ofrenda de cereal que el sacerdote toma con la mano; en Genesis, describe la abundante produccion agricola ''a punados''. El termino deriva del verbo que significa ''agarrar'', captando la capacidad de la mano para contener y medir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7064', 'spa', 'Nido de ave (קֵן), tanto literal como metafórico para moradas seguras en las alturas; compartimento o habitación dentro de una estructura. El sentido ', 'Nido de ave (קֵן), tanto literal como metafórico para moradas seguras en las alturas; compartimento o habitación dentro de una estructura. El sentido literal se fundamenta en la tierna ley de Deuteronomio sobre no tomar al ave madre de su nido (Dt 22:6) y en Dios revolviendo el nido del águila para enseñar a volar a sus crías (Dt 32:11). De ahí, la metáfora se eleva: Balaam ve el asentamiento cenita ''puesto en la roca'' y juega con el nombre del clan —''firme es tu nido (qinnekha)''— (Nm 24:21). Abdías y Jeremías se burlan de Edom por poner su nido entre las estrellas (Abd 4; Jer 49:16), y Habacuc condena a los caldeos por la misma arrogancia (Hab 2:9). Un uso singular y distinto en Génesis 6:14 aplica la palabra a los cuartos o compartimentos dentro del arca de Noé: celdas como nidos dentro de la gran embarcación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7065', 'spa', 'Estar celoso/ser celoso por (pasión posesiva); envidiar (deseo resentido); provocar a celos (Hifil)', 'Estar celoso/ser celoso por (pasión posesiva); envidiar (deseo resentido); provocar a celos (Hifil)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7067', 'spa', 'Celoso — usado exclusivamente de Dios, expresa Su exigencia de devoción y lealtad indivisas.', 'Adjetivo reservado enteramente para describir el carácter de Dios, que aparece seis veces en la Torá. A diferencia de los celos humanos, impulsados por la inseguridad, los celos divinos (qanna) expresan la justa insistencia de un Señor del pacto en que Su pueblo le rinda adoración exclusiva. La palabra retumba por primera vez desde el Sinaí en el segundo mandamiento (Éx 20:5; Deut 5:9), advirtiendo que Dios visita la iniquidad sobre quienes le aborrecen. De manera notable, Éxodo 34:14 declara que «Celoso» es en realidad el nombre de Dios — qanna shemo — haciendo de este atributo no solo una descripción, sino una identidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7068', 'spa', 'Celos, posesividad apasionada; celo o devoción ardiente; envidia o rivalidad resentida', 'Celos, posesividad apasionada; celo o devoción ardiente; envidia o rivalidad resentida');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7069', 'spa', 'Comprar, adquirir; obtener (esp. sabiduría); crear o poseer (referido a Dios); pasivo: ser comprado.', 'Comprar, adquirir; obtener (esp. sabiduría); crear o poseer (referido a Dios); pasivo: ser comprado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7070', 'spa', 'Caña, junco; tallo de grano; brazo o fuste del candelabro; cálamo aromático; barra de balanza; hueso del brazo', 'Caña, junco; tallo de grano; brazo o fuste del candelabro; cálamo aromático; barra de balanza; hueso del brazo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7071', 'spa', 'Caná, nombre de un arroyo y una ciudad en Canaán', 'Caná designa tanto un uadi (arroyo estacional) que marca el límite entre Efraín y Manasés, como una ciudad separada en el territorio de Aser. El arroyo, identificado con el moderno Wady Kânah al suroeste de Nablus, aparece en las descripciones de límites tribales de Josué. La ciudad en Aser, probablemente la moderna Qâna al sureste de Tiro, representa una ubicación geográfica diferente que comparte el mismo nombre, el cual puede derivar de una raíz que significa ''caña'' o ''junco''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7073', 'spa', 'Kenaz, nombre de clan edomita y padre de Otoniel, el primer juez de Israel', 'Nombre propio de persona y clan que aparece tanto en las genealogías edomitas como israelitas. Entre los descendientes de Esaú, Kenaz es nieto de Esaú y jefe de Edom (Gn 36:11, 15, 42). El nombre reaparece en el territorio de Judá como padre de Otoniel, el primer juez de Israel, quien conquistó Debir y ganó a Acsa, hija de Caleb, como esposa (Jos 15:17; Jue 1:13). Este doble uso sugiere los complejos vínculos de parentesco entre Edom y el sur de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7074', 'spa', 'el cenezeo (adjetivo gentilicio)', 'Este adjetivo gentilicio identifica a los miembros del clan o tribu cenezea, asociados con Caleb y enumerados entre los habitantes preisraelitas de Canaan. El termino aparece con articulo, refiriendose a la identidad etnica de Caleb y a un pueblo cananeo del sur mencionado en la promesa de tierra del pacto abrahamico. La herencia cenezea de Caleb resalta el complejo mosaico etnico del Israel primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7075', 'spa', 'Posesiones, bienes o riqueza adquiridos; a veces el acto mismo de adquisición. De la raíz קנה, «comprar, adquirir».', 'El sustantivo קִנְיָן designa lo que se ha obtenido o adquirido: propiedades, posesiones o riquezas vistas como fruto de un esfuerzo o compra previos. Aparece en relatos patriarcales clave: Esaú toma todo su קִנְיָן y parte de Canaán (Gn 36:6), y al pueblo de Siquem se le dice que el ganado y las propiedades de Jacob serán suyos (Gn 34:23). En los Salmos el término se expande bellamente: Sal 104:24 se maravilla de que la tierra esté llena del קִנְיָן de Dios —sus «criaturas» o «adquisiciones», todo lo que Él ha hecho—. Proverbios 4:7 exhorta al lector a invertir todo su קִנְיָן en adquirir sabiduría. Ocasionalmente el énfasis recae sobre la transacción misma más que sobre los bienes resultantes, como cuando Levítico 22:11 habla del קִנְיַן כֶּסֶף del sacerdote, «adquisición por plata».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7076', 'spa', 'canela, especia aromática extraída de corteza usada en culto y perfumería', 'La canela era una especia preciosa importada, probablemente procedente de tierras orientales lejanas, valorada por su fragancia dulce. Aparece en la fórmula del aceite de unción sagrada de Éxodo 30, mezclada con otros aromáticos para consagrar el tabernáculo y los sacerdotes. La palabra es probablemente un préstamo lingüístico extranjero que entró al hebreo junto con el producto exótico mismo, relacionado con el griego κιννάμων. Proverbios y Cantar de los Cantares también la mencionan como perfume de lujo, sugiriendo asociaciones tanto sagradas como sensuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7077', 'spa', 'Anidar, hacer nido; verbo denominativo de qen (nido), usado literalmente de aves y figuradamente de morada segura.', 'Verbo denominativo en Piel derivado de qen (''nido''), que describe el acto de construir un nido o establecerse con seguridad en un lugar protegido. En sentido literal, retrata aves anidando en los árboles: la cigüeña en los cipreses (Sal 104:17) o las aves entre las ramas del gran cedro (Ez 31:6). En sentido figurado, transmite falsa seguridad: Jeremías se burla de la élite de Judá ''anidada entre cedros'' (Jer 22:23), y se insta a Moab a anidar como paloma en el peñasco para escapar del juicio (Jer 48:28). Isaías describe la serpiente anidando en las ruinas de Edom (Isa 34:15), transformando la imagen de consuelo en desolación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7080', 'spa', 'Practicar adivinación, buscar presagios; como participio, un adivino o agorero; el acto y los agentes de la consulta oracular ajena a Yahvé.', 'Practicar adivinación, buscar presagios; como participio, un adivino o agorero; el acto y los agentes de la consulta oracular ajena a Yahvé.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7081', 'spa', 'Adivinación, práctica de buscar conocimiento oculto por medios sobrenaturales; también oráculo o pronunciamiento autoritativo', 'El sustantivo קֶסֶם se refiere a la adivinación: el intento de descubrir el futuro o cosas ocultas por medios sobrenaturales ajenos a los canales dispuestos por el SEÑOR. En la Biblia hebrea aparece casi exclusivamente como práctica prohibida: los honorarios de adivinación de Balaam (Nm 22:7), el acusativo cognado ''el que practica adivinación'' (Dt 18:10) y las adivinaciones mentirosas de los falsos profetas (Ez 13:6). Sin embargo, una notable excepción en Proverbios 16:10 aplica la palabra positivamente a los labios del rey, tratando sus pronunciamientos como una especie de oráculo que no debería errar en el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7083', 'spa', 'estuche de escriba, tintero portátil usado por escribas', 'Este sustantivo designa el equipo de escritura portátil o tintero que los escribas llevaban a su costado, típicamente conteniendo tinta e implementos para escribir. Aparece solamente en la visión de Ezequiel del varón vestido de lino que lleva ''el estuche de escriba'' mientras marca las frentes de los justos en Jerusalén. El término puede ser una forma modificada relacionada con ''arco'' (qeshet), quizás describiendo su forma curvada o cómo colgaba del cinturón del escriba.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7084', 'spa', 'Queila — ciudad fortificada en la Sefela de Judá, famosa como el sitio que David rescató de los filisteos. Queila era una ciudad amurallada en las tie', 'Queila — ciudad fortificada en la Sefela de Judá, famosa como el sitio que David rescató de los filisteos. Queila era una ciudad amurallada en las tierras bajas de Judá, a unos trece kilómetros al noroeste de Hebrón. Su episodio bíblico más dramático es el rescate de la ciudad por David de una incursión filistea contra el grano (1 Sam 23:1–13), tras lo cual Dios advirtió a David que los ciudadanos de Queila lo entregarían a Saúl, lo que motivó su partida. La ciudad aparece en la asignación tribal de Judá en Josué (Jos 15:44) y nuevamente en Nehemías entre quienes repararon secciones del muro de Jerusalén (Neh 3:17–18). Posiblemente corresponde a la ciudad Qiltu de las cartas de Tell el-Amarna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7086', 'spa', 'Fuente, plato, bandeja; vasija poco profunda de plata usada en el servicio del Tabernáculo y las ofrendas de dedicación. Término de utensilio cúltico ', 'Fuente, plato, bandeja; vasija poco profunda de plata usada en el servicio del Tabernáculo y las ofrendas de dedicación. Término de utensilio cúltico que aparece exclusivamente en la fuente sacerdotal. Todas sus diecisiete ocurrencias pertenecen al Tabernáculo o su dedicación: Éxodo 25:29 y 37:16 enumeran la קְעָרָה entre los utensilios de la mesa, mientras que Números 7 la repite doce veces cuando cada líder tribal presenta una fuente de plata que pesa 130 siclos. La consistencia singular de su referente —una fuente metálica poco profunda para el servicio sagrado— se refleja en las diversas traducciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7087a', 'spa', 'cuajar, espesar, solidificarse o estancarse', 'Este verbo describe líquidos que se vuelven espesos, sólidos o estancados, usado en tres contextos dramáticamente diferentes. En Éxodo 15, retrata el milagro en el Mar Rojo donde las aguas ''se cuajaron'' formando muros. Job 10:10 lo usa metafóricamente para la formación de un feto: ''¿No me cuajaste como queso?'' Sofonías lo emplea figurativamente para la complacencia espiritual: gente ''estancada sobre sus heces'' como vino sin remover que se ha vuelto inerte. El hilo común es transformación de líquido a sólido o de activo a estático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7090', 'spa', 'erizo o puercoespín, animal inmundo que habita ruinas', 'Esta criatura (posiblemente erizo, puercoespín o avetoro—los traductores antiguos no concordaban) simboliza desolación en oráculos proféticos. Isaías y Sofonías la invocan al describir tierras reducidas a desierto inhabitable. La identificación permanece incierta, aunque el griego usa ''erizo'' y la Vulgata ''puercoespín''. Ya sea refiriéndose a un mamífero espinoso o ave de pantano, lo clave es su asociación con lugares abandonados y malditos donde la civilización humana ha cesado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7092', 'spa', 'Cerrar, juntar (mano o boca); contraerse; saltar o brincar con energía.', 'En su sentido fundamental, este verbo describe la acción de juntar o contraer, lo cual se manifiesta en contextos sorprendentemente variados. Con mayor frecuencia designa cerrar la mano contra el pobre (Dt 15:7) o cerrar la boca en asombro o silencio (Is 52:15; Job 5:16; Sal 107:42). La angustiada pregunta del salmista — ''¿Ha cerrado (קָפַץ) Dios su compasión?'' (Sal 77:9) — extiende el cierre físico al ámbito emocional. El Nifal en Job 24:24 pasa a la contracción pasiva: los malvados ''son recogidos'' y se marchitan. Y de forma inesperada, el Piel en Cantares 2:8 describe al amado ''brincando'' (מְקַפֵּץ) sobre los montes, donde la contracción muscular se transforma en impulso elástico de salto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7093', 'spa', 'Fin o límite de un período de tiempo; por extensión, el extremo espacial más lejano o frontera.', 'Fin o límite de un período de tiempo; por extensión, el extremo espacial más lejano o frontera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7095', 'spa', 'forma, figura; extremidad o base (de montañas)', 'Este sustantivo porta dos significados relacionados: la forma o figura medida de los muebles del templo, y los límites extremos o bases de características geográficas. En 1 Reyes, describe las dimensiones estandarizadas y formas de los querubines y basas de bronce en el templo de Salomón. Jonás lo usa poéticamente para ''las raíces de los montes'' o sus fundamentos submarinos, sugiriendo las profundidades absolutas del mar donde el profeta se imaginó atrapado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7096', 'spa', 'Cortar, raspar, cercenar; destruir o disminuir (pueblos, miembros, superficies)', 'Verbo de separacion y remocion empleado en contextos variados. En Levitico 14:41,43 el Hifil describe el raspado del enlucido de las paredes de una casa sospechosa de ''lepra'', como parte de un procedimiento sacerdotal de purificacion. En 2 Reyes 10:32 Dios comienza a ''cercenar'' porciones de Israel mediante las incursiones de Hazael. Habacuc 2:10 condena a quien se enriquece ''cortando a muchos pueblos''. El uso figurado en Proverbios 26:6 retrata al mensajero necio como aquel que ''se corta los pies'', es decir, se perjudica a si mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7097a', 'spa', 'Extremo, punta, borde de un objeto; el confín más lejano de un territorio o de la tierra; el fin de un período de tiempo.', 'Extremo, punta, borde de un objeto; el confín más lejano de un territorio o de la tierra; el fin de un período de tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7097b', 'spa', 'Fin, limite; usado en la frase ''sin fin'' para indicar lo ilimitado', 'Sustantivo que significa ''fin'' o ''limite'', y que aparece exclusivamente en la expresion fija ''no hay fin de'' (אֵין קֵצֶה). Isaias 2:7 lo emplea dos veces: no hay fin de la plata y el oro de Juda, ni de sus carros, como ironica denuncia del exceso materialista. Nahum recurre a la misma construccion para referirse a la riqueza saqueada de Ninive (2:9), sus cadaveres amontonados (3:3) y su fuerza sin limite (3:9). En cada caso la negacion del limite expresa cantidad inagotable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7098', 'spa', 'Extremo, extremidad o borde de un objeto físico; los confines más lejanos de la tierra o un territorio', 'Extremo, extremidad o borde de un objeto físico; los confines más lejanos de la tierra o un territorio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7099', 'spa', 'extremos, límites o confines (especialmente de la tierra o territorio)', 'Este sustantivo plural designa los alcances más lejanos o los límites del espacio geográfico. Los Salmos usan ''los confines de la tierra'' para expresar el alcance universal de Dios y su reputación, mientras que Isaías lo aplica a la expansión territorial de las fronteras de la tierra. El término enfatiza extremidad y totalidad—ya sea la extensión completa del mundo conocido o los límites completos de un territorio particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7100', 'spa', 'comino negro (Nigella sativa), semilla aromática usada como especia', 'El comino negro, también llamado neguilla o ajenuz, es una planta que produce pequeñas semillas negras aromáticas usadas como condimento en la cocina del antiguo Cercano Oriente. Isaías 28 discute su cultivo y trilla en una extensa metáfora agrícola sobre los tratos variados de Dios con Su pueblo. A diferencia del grano trillado con instrumentos pesados, el comino negro se golpeaba con una vara para evitar aplastar las semillas delicadas—un detalle que el profeta usa para ilustrar la sabiduría divina en la disciplina apropiada y medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7101', 'spa', 'Jefe, gobernante o comandante; líder que ejerce autoridad civil o mando militar', 'Sustantivo que describe a una persona en posición de liderazgo autoritativo, civil o militar. En los profetas, designa gobernantes y magistrados: Isaías se dirige a los ''gobernantes de Sodoma'' (Is 1:10) y advierte que los dirigentes de Jerusalén han fallado (Is 3:6-7; 22:3). Miqueas acusa a los ''gobernantes de la casa de Israel'' (Mi 3:1, 9). En contextos militares, denota un comandante, como cuando los capitanes de Josué ponen sus pies sobre los cuellos de reyes derrotados (Jos 10:24) o Jefté es nombrado comandante (Jue 11:6, 11). Proverbios 6:7 observa que las hormigas no tienen qāṣīn y sin embargo cumplen su labor, haciendo de la ausencia de gobernante el motivo de admiración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7105a', 'spa', 'Cosecha: la estación, el acto o el producto recogido de la siega de granos y frutos.', 'Cosecha: la estación, el acto o el producto recogido de la siega de granos y frutos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7105b', 'spa', 'Rama(s), ramaje; colectivamente, la vegetacion frondosa de un arbol (distinto del homonimo ''cosecha'')', 'No debe confundirse con el homonimo comun que significa ''cosecha''; este sustantivo designa las ramas o el ramaje de un arbol, generalmente en sentido colectivo. Job lo emplea tres veces en rico lenguaje metaforico: raices y ramas representan la vida completa de una persona (18:16; 29:19), y hasta un arbol talado puede retonar nuevas ramas (14:9). El Salmo 80:11 representa a Israel como una vid cuyo ramaje cubre los cedros imponentes, mientras Isaias 27:11 describe ramas secas usadas como lena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7107', 'spa', 'Estar airado, enojarse (Qal, de Dios o humanos); provocar a ira (Hifil, causar ira divina); enfurecerse (Hitpael, furia intensificada)', 'Estar airado, enojarse (Qal, de Dios o humanos); provocar a ira (Hifil, causar ira divina); enfurecerse (Hitpael, furia intensificada)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7110a', 'spa', 'Ira, furor intenso — indignación vehemente, atribuida abrumadoramente al enojo furioso de Dios en el juicio.', 'Ira, furor intenso — indignación vehemente, atribuida abrumadoramente al enojo furioso de Dios en el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7112', 'spa', 'Cortar, cercenar o desbastar (קָצַץ); incluye recortar el cabello de las sienes y romper objetos en pedazos. Un verbo de separación física decisiva, u', 'Cortar, cercenar o desbastar (קָצַץ); incluye recortar el cabello de las sienes y romper objetos en pedazos. Un verbo de separación física decisiva, usado para cortar pulgares y dedos gordos de los pies (Jue 1:6), desmontar paneles de carros (2 R 16:17) e incluso cortar hilos de oro para tejer (Éx 39:3). Jeremías aplica el participio pasivo a pueblos que ''se rapan las sienes'' —un rito pagano de duelo que los distinguía de Israel. La evidencia multilingüe confirma el rango semántico: el español ''cortó'' capta la acción básica, mientras que el hindi टुकड़े किए (''hizo pedazos'') refleja el sentido intensivo de fragmentación que se observa en 2 Reyes 24:13.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7114a', 'spa', 'Verbo cuyo sentido físico — ser corto o insuficiente — se extiende a un vívido territorio figurado. Cuando se empareja con ''mano'' (yad), describe impo', 'Verbo cuyo sentido físico — ser corto o insuficiente — se extiende a un vívido territorio figurado. Cuando se empareja con ''mano'' (yad), describe impotencia: ''¿Acaso se ha acortado la mano del SEÑOR para salvar?'' (Isa 50:2; Núm 11:23). Cuando se empareja con ''alma'' (néfesh) o ''espíritu'' (rúaj), capta la constricción interior de la impaciencia, como cuando el alma de Israel ''se acortó'' en el camino del desierto (Núm 21:4). El Hifil y el Piel extienden el significado a acortar activamente o abreviar los días de alguien (Sal 89:45; 102:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7114b', 'spa', 'Segar o cosechar grano; cortar y recoger una cosecha, en sentido literal o figurado', 'Segar o cosechar grano; cortar y recoger una cosecha, en sentido literal o figurado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7116', 'spa', 'Corto (de mano: debil; de espiritu: impaciente; de dias: efimero)', 'Adjetivo que significa ''corto'' y que nunca aparece solo, sino siempre en construccion con otro sustantivo, generando vividos sentidos figurados. ''Corto de mano'' (2 R 19:26; Is 37:27) describe la debilidad de las naciones ante Dios. ''Corto de espiritu'' o ''corto de genio'' (Pr 14:17,29) caracteriza al impaciente, en contraste con quien es ''lento para la ira''. ''Corto de dias'' (Job 14:1) capta la brevedad de la vida humana. La expresion ''corto de'' refleja fielmente el patron constructo hebreo donde la brevedad fisica se convierte en metafora de limitacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7117', 'spa', 'Fin, extremo (espacial o temporal); en uso partitivo, ''parte de, algunos de''.', 'Sustantivo que capta la idea de borde, límite o punto terminal, ya sea espacial o temporal. En Éxodo 38:5 describe las cuatro esquinas del enrejado de bronce, mientras que en Daniel 1:5 y 1:15 marca el final de un período de días (''al cabo de''). Pero la palabra también desarrolló un uso partitivo distintivo, especialmente en el hebreo bíblico tardío: ''parte de los utensilios'' (Dn 1:2), ''algunos de los jefes de familias'' (Neh 7:70). La evidencia del árabe resulta instructiva: nihayah (نِهَايَة) para el sentido espacial/temporal, ba''da (بَعْضَ) para el partitivo, lo que confirma que se trata de funciones semánticas genuinamente distintas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7118', 'spa', 'fin (arameo); parte o porción', 'Este sustantivo arameo aparece en Daniel con dos sentidos relacionados: el fin o conclusión de un período de tiempo, y una parte o porción de algo. En Daniel 4, marca la finalización de meses (''al cabo de doce meses''), mientras que en el capítulo 2 indica un elemento parcial (''parte del reino''). El término funciona de manera similar al hebreo qetsah, marcando límites en tiempo o composición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7119', 'spa', 'fresco, frío (literalmente de agua; figuradamente de temperamento)', 'Este adjetivo describe frescura refrescante, aplicado tanto al agua como metafóricamente a la disposición. Proverbios celebra dos veces el agua fría—de tierras distantes o en circunstancias sedientas—como supremamente refrescante. El Ketiv de Proverbios 17:27 lo usa figuradamente para ''fresco de espíritu'', significando calmado y sereno, aunque la lectura del Qere difiere. Jeremías habla de aguas frías que fluyen en contraste con arroyos no confiables, enfatizando dependabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7121', 'spa', 'Llamar, convocar, nombrar; clamar en angustia; proclamar públicamente; leer en voz alta; invitar a reunión', 'Verbo fundamental de acción vocal en el hebreo bíblico, קָרָא abarca el espectro completo desde nombrar a un niño (Gn 2:19) hasta clamar a Dios en agonía (Jue 15:18) y leer en voz alta el rollo de la Torá ante la asamblea (Dt 31:11). El árabe conserva una escisión reveladora: da''a cubre llamar y convocar, mientras que qara''a se especializa en lectura y recitación — la misma raíz que da origen a ''Corán''. El coreano distingue de modo similar 부르다 (llamar/nombrar) de 읽다 (leer) y 부르짖다 (clamar), confirmando que se trata de acepciones genuinamente distintas dentro de un solo lexema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7122', 'spa', 'Encontrar, hallar, sobrevenir; usado para encuentros deliberados, encuentros casuales y calamidades que sobrevienen', 'Encontrar, hallar, sobrevenir; usado para encuentros deliberados, encuentros casuales y calamidades que sobrevienen');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7123', 'spa', 'Clamar, proclamar; leer en voz alta (arameo, principalmente en Daniel y Esdras)', 'El equivalente arameo del hebreo qara'', este verbo porta los sentidos gemelos de proclamación vocal y lectura pública que definen la comunicación oficial en el antiguo Cercano Oriente. En Daniel 3:4, un heraldo ''proclama con fuerza'', destacando la autoridad del anunciador. El sentido de lectura domina Daniel 5, donde los sabios son convocados para ''leer'' la misteriosa escritura en la pared. El Hitpe''el pasivo en Daniel 5:12 añade el matiz de ser convocado oficialmente, ''que se llame a Daniel'', mostrando cómo la proclamación y la convocatoria son dos caras del mismo acto de habla pública.');